void AudioEngine::setTrackMIDIOutput(const juce::String& trackId, const juce::String& deviceName)
{
    auto it = trackMap.find(trackId);
    if (it != trackMap.end()) it->second->setMIDIOutputDevice(deviceName);
}

juce::String AudioEngine::getTrackMIDIOutput(const juce::String& trackId) const
{
    auto it = trackMap.find(trackId);
    return it != trackMap.end() ? it->second->getMIDIOutputDeviceName() : juce::String();
}

juce::var AudioEngine::getTrackRoutingInfo(const juce::String& trackId)
{
    auto it = trackMap.find(trackId);
    if (it == trackMap.end()) return juce::var();

    auto* track = it->second;
    auto* obj = new juce::DynamicObject();

    obj->setProperty("phaseInverted", track->getPhaseInvert());
    obj->setProperty("stereoWidth", track->getStereoWidth());
    obj->setProperty("masterSendEnabled", track->getMasterSendEnabled());
    obj->setProperty("outputStartChannel", track->getOutputStartChannel());
    obj->setProperty("outputChannelCount", track->getOutputChannelCount());
    obj->setProperty("playbackOffsetMs", track->getPlaybackOffset());
    obj->setProperty("trackChannelCount", track->getTrackChannelCount());
    obj->setProperty("midiOutputDevice", track->getMIDIOutputDeviceName());
    obj->setProperty("inputStartChannel", track->getInputStartChannel());
    obj->setProperty("inputChannelCount", track->getInputChannelCount());
    obj->setProperty("inputMonitoring", track->getInputMonitoring());
    obj->setProperty("recordArmed", track->getRecordArmed());
    const auto trackType = track->getTrackType();
    obj->setProperty("trackType", trackType == TrackType::Instrument
        ? "instrument"
        : (trackType == TrackType::MIDI ? "midi" : "audio"));

    return juce::var(obj);
}

juce::var AudioEngine::getMidiDiagnostics() const
{
    juce::Array<juce::var> tracksArray;
    int midiTrackCount = 0;
    int instrumentTrackCount = 0;
    int scheduledTrackCount = 0;
    int scheduledClipCount = 0;
    int scheduledEventCount = 0;
    int tracksWithMidiOutput = 0;

    for (const auto& [trackId, track] : trackMap)
    {
        if (!track)
            continue;

        const auto type = track->getTrackType();
        const int trackScheduledClips = track->getScheduledMIDIClipCount();
        const int trackScheduledEvents = track->getScheduledMIDIEventCount();
        if (type == TrackType::MIDI)
            ++midiTrackCount;
        else if (type == TrackType::Instrument)
            ++instrumentTrackCount;
        if (trackScheduledClips > 0 || trackScheduledEvents > 0)
            ++scheduledTrackCount;
        scheduledClipCount += trackScheduledClips;
        scheduledEventCount += trackScheduledEvents;
        if (track->getMIDIOutputDeviceName().isNotEmpty())
            ++tracksWithMidiOutput;

        auto* trackObj = new juce::DynamicObject();
        trackObj->setProperty("trackId", trackId);
        trackObj->setProperty("trackType", type == TrackType::Instrument
            ? "instrument"
            : (type == TrackType::MIDI ? "midi" : "audio"));
        trackObj->setProperty("midiOverflowCount", track->getMidiOverflowCount());
        trackObj->setProperty("lastBuiltMidiEventCount", track->getLastBuiltMidiEventCount());
        trackObj->setProperty("maxBuiltMidiEventCount", track->getMaxBuiltMidiEventCount());
        trackObj->setProperty("scheduledMIDIClipCount", trackScheduledClips);
        trackObj->setProperty("scheduledMIDIEventCount", trackScheduledEvents);
        trackObj->setProperty("hasInstrument", track->getInstrument() != nullptr);
        trackObj->setProperty("instrumentName", track->getInstrument() != nullptr ? track->getInstrument()->getName() : juce::String());
        trackObj->setProperty("fallbackInstrumentActive", track->isUsingFallbackInstrument());
        const auto fallbackSamplerPath = track->getFallbackSamplerSamplePath();
        trackObj->setProperty("fallbackSamplerActive", track->hasFallbackSamplerSample());
        trackObj->setProperty("fallbackSamplerSamplePath", fallbackSamplerPath);
        trackObj->setProperty("fallbackSamplerSourceType", fallbackSamplerPath.endsWithIgnoreCase(".sf2")
            ? "soundfont"
            : (fallbackSamplerPath.isNotEmpty() ? "audio" : ""));
        trackObj->setProperty("midiInputDevice", track->getMIDIInputDevice());
        trackObj->setProperty("midiChannel", track->getMIDIChannel());
        trackObj->setProperty("midiOutputDevice", track->getMIDIOutputDeviceName());
        trackObj->setProperty("muted", track->getMute());
        trackObj->setProperty("midiOutputMutedSuppressed",
                              track->getMute() && track->getMIDIOutputDeviceName().isNotEmpty());
        trackObj->setProperty("acceptsMidi", track->acceptsMidi());
        trackObj->setProperty("producesMidi", track->producesMidi());
        trackObj->setProperty("inputFXCount", track->getNumInputFX());
        trackObj->setProperty("trackFXCount", track->getNumTrackFX());
        trackObj->setProperty("realtimeFallbackReuseCount", track->getRealtimeFallbackReuseCount());
        trackObj->setProperty("monitoring", track->getInputMonitoring());
        trackObj->setProperty("recordArmed", track->getRecordArmed());
        tracksArray.add(juce::var(trackObj));
    }

    juce::Array<juce::var> inputDevicesArray;
    juce::Array<juce::var> openDevicesArray;
    if (midiManager)
    {
        for (const auto& device : midiManager->getAvailableDevices())
            inputDevicesArray.add(device);
        for (const auto& device : midiManager->getOpenDevices())
            openDevicesArray.add(device);
    }

    juce::Array<juce::var> outputDevicesArray;
    for (const auto& device : juce::MidiOutput::getAvailableDevices())
        outputDevicesArray.add(device.name);

    auto* root = new juce::DynamicObject();
    root->setProperty("tracks", tracksArray);
    root->setProperty("inputDevices", inputDevicesArray);
    root->setProperty("outputDevices", outputDevicesArray);
    root->setProperty("openDevices", openDevicesArray);
    root->setProperty("trackCount", static_cast<int>(trackMap.size()));
    root->setProperty("midiTrackCount", midiTrackCount);
    root->setProperty("instrumentTrackCount", instrumentTrackCount);
    root->setProperty("scheduledMIDITrackCount", scheduledTrackCount);
    root->setProperty("scheduledMIDIClipCount", scheduledClipCount);
    root->setProperty("scheduledMIDIEventCount", scheduledEventCount);
    root->setProperty("tracksWithMidiOutput", tracksWithMidiOutput);
    root->setProperty("bufferSize", currentBlockSize);
    root->setProperty("sampleRate", currentSampleRate);
    root->setProperty("lateEventCount", midiLateEventCount.load(std::memory_order_relaxed));
    root->setProperty("maxEventsPerBlock", midiMaxEventsPerBlock.load(std::memory_order_relaxed));
    root->setProperty("lastComputedSampleOffset", midiLastComputedSampleOffset.load(std::memory_order_relaxed));
    root->setProperty("masterFXFallbackReuseCount", masterFXFallbackReuseCount.load(std::memory_order_relaxed));
    root->setProperty("monitoringFXFallbackReuseCount", monitoringFXFallbackReuseCount.load(std::memory_order_relaxed));
    root->setProperty("masterFXBusySkipCount", masterFXBusySkipCount.load(std::memory_order_relaxed));
    root->setProperty("monitoringFXBusySkipCount", monitoringFXBusySkipCount.load(std::memory_order_relaxed));
    root->setProperty("masterStageGeneration", static_cast<int64>(masterStageGeneration.load(std::memory_order_relaxed)));
    root->setProperty("monitoringStageGeneration", static_cast<int64>(monitoringStageGeneration.load(std::memory_order_relaxed)));
    root->setProperty("masterStageBuildFailureCount", masterStageBuildFailureCount.load(std::memory_order_relaxed));
    root->setProperty("monitoringStageBuildFailureCount", monitoringStageBuildFailureCount.load(std::memory_order_relaxed));
    root->setProperty("masterStageLastBuildMs", masterStageLastBuildMs.load(std::memory_order_relaxed));
    root->setProperty("monitoringStageLastBuildMs", monitoringStageLastBuildMs.load(std::memory_order_relaxed));
    root->setProperty("processingPrecision", getProcessingPrecision());
    return juce::var(root);
}

juce::var AudioEngine::getAudioDebugSnapshot() const
{
    juce::Array<juce::var> playbackTracks;
    for (const auto& [trackId, track] : trackMap)
    {
        auto* trackObj = new juce::DynamicObject();
        trackObj->setProperty("trackId", trackId);
        trackObj->setProperty("clipCount", playbackEngine.getNumClipsForTrack(trackId));
        if (track != nullptr)
        {
            trackObj->setProperty("pluginBusySkipCount", track->getPluginBusySkipCount());
            trackObj->setProperty("midiOverflowCount", track->getMidiOverflowCount());
            trackObj->setProperty("lastBuiltMidiEventCount", track->getLastBuiltMidiEventCount());
            trackObj->setProperty("maxBuiltMidiEventCount", track->getMaxBuiltMidiEventCount());
            trackObj->setProperty("scheduledMIDIClipCount", track->getScheduledMIDIClipCount());
            trackObj->setProperty("scheduledMIDIEventCount", track->getScheduledMIDIEventCount());
            trackObj->setProperty("inputFXCount", track->getNumInputFX());
            trackObj->setProperty("trackFXCount", track->getNumTrackFX());
            trackObj->setProperty("isInstrument", track->getTrackType() == TrackType::Instrument);
            trackObj->setProperty("hasInstrument", track->getInstrument() != nullptr);
            trackObj->setProperty("instrumentName", track->getInstrument() != nullptr ? track->getInstrument()->getName() : juce::String());
            trackObj->setProperty("fallbackInstrumentActive", track->isUsingFallbackInstrument());
            const auto fallbackSamplerPath = track->getFallbackSamplerSamplePath();
            trackObj->setProperty("fallbackSamplerActive", track->hasFallbackSamplerSample());
            trackObj->setProperty("fallbackSamplerSamplePath", fallbackSamplerPath);
            trackObj->setProperty("fallbackSamplerSourceType", fallbackSamplerPath.endsWithIgnoreCase(".sf2")
                ? "soundfont"
                : (fallbackSamplerPath.isNotEmpty() ? "audio" : ""));
            trackObj->setProperty("recordArmed", track->getRecordArmed());
            trackObj->setProperty("inputMonitoring", track->getInputMonitoring());
        }
        playbackTracks.add(juce::var(trackObj));
    }

    auto* root = new juce::DynamicObject();
    root->setProperty("transportPlaying", isPlaying.load());
    root->setProperty("transportRecording", isRecordMode.load());
    root->setProperty("transportPosition", getTransportPosition());
    root->setProperty("sampleRate", currentSampleRate);
    root->setProperty("blockSize", currentBlockSize);
    root->setProperty("audioDeviceXRunCount", deviceManager.getXRunCount());
#if JUCE_WINDOWS
    const auto cpuUsagePercent = getProcessCpuUsagePercent();
    if (cpuUsagePercent >= 0.0)
        root->setProperty("cpuUsage", cpuUsagePercent);
#endif
    root->setProperty("playbackClipCount", playbackEngine.getNumClips());
    root->setProperty("activeOutputChannels", lastActiveOutputChannels.load(std::memory_order_relaxed));
    root->setProperty("callbackInputChannels", lastCallbackInputChannels.load(std::memory_order_relaxed));
    root->setProperty("callbackOutputChannels", lastCallbackOutputChannels.load(std::memory_order_relaxed));
    root->setProperty("lastCallbackCounter", static_cast<int64>(lastAudioCallbackCounter.load(std::memory_order_relaxed)));
    root->setProperty("lastAudioCallbackProcessMs", lastAudioCallbackProcessMs.load(std::memory_order_relaxed));
    root->setProperty("maxAudioCallbackProcessMs", maxAudioCallbackProcessMs.load(std::memory_order_relaxed));
    root->setProperty("audioCallbackDeadlineMissCount", static_cast<int64>(audioCallbackDeadlineMissCount.load(std::memory_order_relaxed)));
    root->setProperty("lastAudioCallbackDeadlineMissCounter", static_cast<int64>(lastAudioCallbackDeadlineMissCounter.load(std::memory_order_relaxed)));
    root->setProperty("audioCallbackDeadlineMissBurstCount", static_cast<int64>(audioCallbackDeadlineMissBurstCount.load(std::memory_order_relaxed)));
    root->setProperty("lastAudioCallbackDeadlineMissProcessMs", lastAudioCallbackDeadlineMissProcessMs.load(std::memory_order_relaxed));
    root->setProperty("lastAudioCallbackDeadlineMissWhileRecording", lastAudioCallbackDeadlineMissWhileRecording.load(std::memory_order_relaxed));
    root->setProperty("audioCallbackScopedNoDenormalsCount", static_cast<int64>(audioCallbackScopedNoDenormalsCount.load(std::memory_order_relaxed)));
    root->setProperty("audioCallbackTrackBufferResizeCount", audioCallbackTrackBufferResizeCount.load(std::memory_order_relaxed));
    root->setProperty("audioCallbackPitchScrubBufferResizeCount", audioCallbackPitchScrubBufferResizeCount.load(std::memory_order_relaxed));
    root->setProperty("audioCallbackSidechainBufferResizeCount", audioCallbackSidechainBufferResizeCount.load(std::memory_order_relaxed));
    root->setProperty("crashBreadcrumbLogPath", OpenStudioCrashDiagnostics::getBreadcrumbLogFile().getFullPathName());
    root->setProperty("lastCrashDumpPath", OpenStudioCrashDiagnostics::getLastCrashDumpFile().getFullPathName());
    root->setProperty("spectrumFftPublishCount", static_cast<int64>(spectrumFftPublishCount.load(std::memory_order_relaxed)));
    root->setProperty("spectrumFftLockMissCount", static_cast<int64>(spectrumFftLockMissCount.load(std::memory_order_relaxed)));
    root->setProperty("postTrackPlaybackPeak", lastPostTrackPlaybackPeak.load(std::memory_order_relaxed));
    root->setProperty("postMonitoringInputPeak", lastPostMonitoringInputPeak.load(std::memory_order_relaxed));
    root->setProperty("postMasterFxPeak", lastPostMasterFXPeak.load(std::memory_order_relaxed));
    root->setProperty("postMonitoringFxPeak", lastPostMonitoringFXPeak.load(std::memory_order_relaxed));
    root->setProperty("finalOutputPeak", lastFinalOutputPeak.load(std::memory_order_relaxed));
    const auto tunerFrequency = tunerDetectedFrequencyHz.load(std::memory_order_relaxed);
    const auto tunerLevelDb = tunerInputLevelDb.load(std::memory_order_relaxed);
    const auto tunerConf = tunerConfidence.load(std::memory_order_relaxed);
    const auto tunerLastInput = tunerLastInputCallbackCounter.load(std::memory_order_relaxed);
    const auto currentCallback = lastAudioCallbackCounter.load(std::memory_order_relaxed);
    const bool tunerRecent = tunerLastInput > 0 && currentCallback <= tunerLastInput + 128;
    const bool tunerSignalPresent = tunerRecent && tunerLevelDb > -84.0f;
    const bool tunerPitchLocked = tunerSignalPresent && tunerFrequency > 0.0f && tunerConf >= 0.18f;
    const int tunerMidiNote = tunerPitchLocked ? midiNoteFromFrequencyHz(tunerFrequency) : -1;
    const double tunerCents = tunerPitchLocked ? centsFromFrequencyHz(tunerFrequency, tunerMidiNote) : 0.0;
    root->setProperty("tunerFrequencyHz", tunerPitchLocked ? tunerFrequency : 0.0f);
    root->setProperty("tunerMidiNote", tunerMidiNote);
    root->setProperty("tunerNoteName", tunerPitchLocked ? tunerNoteNameFromMidi(tunerMidiNote) : juce::String());
    root->setProperty("tunerCents", tunerCents);
    root->setProperty("tunerConfidence", tunerPitchLocked ? tunerConf : 0.0f);
    root->setProperty("tunerInputLevelDb", tunerLevelDb);
    root->setProperty("tunerSignalPresent", tunerSignalPresent);
    root->setProperty("tunerPitchLocked", tunerPitchLocked);
    root->setProperty("tunerUpdateCounter", static_cast<int64>(tunerLastInput));
    root->setProperty("tunerInputStartChannel", tunerInputStartChannel.load(std::memory_order_relaxed));
    root->setProperty("tunerInputChannelCount", tunerInputChannelCount.load(std::memory_order_relaxed));
    root->setProperty("lastRecordingClipCountReturned", lastReturnedRecordingClipCount.load(std::memory_order_relaxed));
    root->setProperty("midiLastInputFanoutCount", midiLastInputFanoutCount.load(std::memory_order_relaxed));
    root->setProperty("midiMaxInputFanoutCount", midiMaxInputFanoutCount.load(std::memory_order_relaxed));
    root->setProperty("midiMappedParameterUpdateCount", midiMappedParameterUpdateCount.load(std::memory_order_relaxed));
    root->setProperty("playbackTryLockFailureCount", playbackEngine.getTryLockFailureCount());
    root->setProperty("playbackMissingReaderCount", playbackEngine.getMissingReaderCount());
    root->setProperty("lastOverlappingClipCount", playbackEngine.getLastOverlappingClipCount());
    root->setProperty("lastMixedClipCount", playbackEngine.getLastMixedClipCount());
    root->setProperty("lastTrackPlaybackPeak", playbackEngine.getLastTrackPlaybackPeak());
    root->setProperty("playbackFileBufferResizeCount", playbackEngine.getFileBufferResizeCount());
    root->setProperty("playbackPitchShiftWorkBufferResizeCount", playbackEngine.getPitchShiftWorkBufferResizeCount());
    root->setProperty("playbackRenderResampleScratchResizeCount", playbackEngine.getRenderResampleScratchResizeCount());
    root->setProperty("playbackChunkBoundaryReserveCount", playbackEngine.getChunkBoundaryReserveCount());
    root->setProperty("playbackAudioDataCacheMissCount", playbackEngine.getAudioDataCacheMissCount());
    root->setProperty("playbackAudioDataCachedFileCount", playbackEngine.getAudioDataCachedFileCount());
    const auto pitchRouting = playbackEngine.getPitchPreviewRoutingStatus({});
    root->setProperty("pitchRouteMonitorMode", pitchRouting.monitorMode);
    root->setProperty("pitchRouteRenderedSegmentActive", pitchRouting.renderedSegmentActive);
    root->setProperty("pitchRouteClipLivePreviewActive", pitchRouting.clipLivePreviewActive);
    root->setProperty("pitchRouteScrubPreviewActive", pitchRouting.scrubPreviewActive);
    root->setProperty("pitchRouteCorrectedSourceActive", pitchRouting.correctedSourceActive);
    root->setProperty("playbackTracks", playbackTracks);
    return juce::var(root);
}

juce::String AudioEngine::renderMetronomeToFile(double startTime, double endTime)
{
    // Create output file in the preferred OpenStudio audio directory, while
    // still following the legacy Studio13 location if an existing install uses it.
    auto audioFolder = getPreferredAppDataDirectory().getChildFile("Audio");

    if (!audioFolder.exists())
        audioFolder.createDirectory();

    auto timestamp = juce::Time::getCurrentTime().toMilliseconds();
    auto filename = "Metronome_" + juce::String(timestamp) + ".wav";
    auto outputFile = audioFolder.getChildFile(filename);

    // Create a dedicated Metronome instance for offline rendering
    // (to avoid interfering with the real-time metronome)
    Metronome renderMetronome;
    renderMetronome.prepareToPlay(currentSampleRate, 512);
    renderMetronome.setBpm(tempo);
    renderMetronome.setTimeSignature(timeSigNumerator, timeSigDenominator);
    renderMetronome.setVolume(metronome.getVolume());
    renderMetronome.setAccentBeats(metronome.getAccentBeats());

    bool success = renderMetronome.renderToFile(outputFile, startTime, endTime);

    if (success)
    {
        juce::Logger::writeToLog("AudioEngine: Rendered metronome to: " + outputFile.getFullPathName());
        return outputFile.getFullPathName();
    }

    juce::Logger::writeToLog("AudioEngine: Failed to render metronome");
    return {};
}

//==============================================================================
// Plugin State Serialization (F2 - Project Save/Load)

juce::String AudioEngine::getPluginState(const juce::String& trackId, int fxIndex, bool isInputFX)
{
    const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
    if (trackMap.find(trackId) == trackMap.end())
        return {};
    
    auto* track = trackMap[trackId];
    if (!track)
        return {};
    
    juce::AudioProcessor* processor = nullptr;
    
    if (isInputFX)
    {
        if (fxIndex >= 0 && fxIndex < track->getNumInputFX())
            processor = track->getInputFXProcessor(fxIndex);
    }
    else
    {
        if (fxIndex >= 0 && fxIndex < track->getNumTrackFX())
            processor = track->getTrackFXProcessor(fxIndex);
    }
    
    if (!processor)
        return {};
    
    // Get plugin state as memory block
    juce::MemoryBlock stateData;
    {
        const juce::ScopedLock processorLock(processor->getCallbackLock());
        processor->getStateInformation(stateData);
    }
    
    // Convert to Base64 string
    return stateData.toBase64Encoding();
}

bool AudioEngine::setPluginState(
    const juce::String& trackId,
    int fxIndex,
    bool isInputFX,
    const juce::String& base64State,
    const std::function<std::shared_ptr<void>()>& publicationLeaseFactory)
{
    // Decode Base64 to memory block
    juce::MemoryBlock stateData;
    if (!stateData.fromBase64Encoding(base64State))
        return false;

    std::shared_ptr<juce::AudioProcessor> processorOwner;
    {
        const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
        auto it = trackMap.find(trackId);
        if (it == trackMap.end() || it->second == nullptr)
            return false;

        processorOwner = isInputFX
            ? it->second->getInputFXProcessorShared(fxIndex)
            : it->second->getTrackFXProcessorShared(fxIndex);
    }

    auto* processor = processorOwner.get();
    if (processor == nullptr)
        return false;

    int latencyBefore = 0;
    int latencyAfter = 0;
    bool restored = false;
    if (auto* rack = dynamic_cast<S13NAMRack*>(processor))
    {
        latencyBefore = processor->getLatencySamples();
        restored = rack->restoreProjectStateInformation(
            stateData.getData(),
            static_cast<int>(stateData.getSize()),
            publicationLeaseFactory);
        latencyAfter = processor->getLatencySamples();
    }
    else
    {
        std::shared_ptr<void> publicationLease;
        if (publicationLeaseFactory)
        {
            publicationLease = publicationLeaseFactory();
            if (! publicationLease)
                return false;
        }
        const juce::ScopedLock processorLock(processor->getCallbackLock());
        latencyBefore = processor->getLatencySamples();
        processor->setStateInformation(stateData.getData(), static_cast<int>(stateData.getSize()));
        latencyAfter = processor->getLatencySamples();
        restored = true;
    }

    if (! restored)
        return false;

    {
        const juce::ScopedLock graphLock(mainProcessorGraph->getCallbackLock());
        const auto trackIt = trackMap.find(trackId);
        if (trackIt != trackMap.end() && trackIt->second != nullptr)
            trackIt->second->invalidatePluginAutomationCache();
    }

    if (latencyAfter != latencyBefore)
        recalculatePDC();

    juce::Logger::writeToLog("AudioEngine: Restored plugin state for track " + trackId + 
                             " FX " + juce::String(fxIndex) + " (isInput: " + (isInputFX ? "true" : "false") + ")");
    return true;
}

juce::String AudioEngine::getMasterPluginState(int fxIndex)
{
    int slotId = 0;
    juce::String cachedState;
    {
        const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
        if (const auto* slot = findDesiredStageSlot(desiredMasterStageSpec, fxIndex))
        {
            slotId = slot->slotId;
            cachedState = slot->serializedState;
        }
    }

    if (slotId == 0)
        return {};

    auto activeStage = std::atomic_load_explicit(&realtimeMasterFXSnapshot, std::memory_order_acquire);
    if (const auto* activeSlot = findActiveStageSlot(activeStage, slotId))
        return serialiseProcessorStateToBase64(activeSlot->processor.get());

    return cachedState;
}

bool AudioEngine::isMasterNAMRackPlugin(int fxIndex)
{
    int slotId = 0;
    {
        const juce::ScopedLock graphLock(mainProcessorGraph->getCallbackLock());
        if (const auto* slot = findDesiredStageSlot(desiredMasterStageSpec, fxIndex))
            slotId = slot->slotId;
    }
    if (slotId == 0)
        return false;

    const auto activeStage = std::atomic_load_explicit(
        &realtimeMasterFXSnapshot, std::memory_order_acquire);
    const auto* activeSlot = findActiveStageSlot(activeStage, slotId);
    return activeSlot != nullptr
        && dynamic_cast<S13NAMRack*>(activeSlot->processor.get()) != nullptr;
}

bool AudioEngine::setMasterPluginState(
    int fxIndex,
    const juce::String& base64State,
    const std::function<std::shared_ptr<void>()>& publicationLeaseFactory)
{
    juce::MemoryBlock stateData;
    if (!stateData.fromBase64Encoding(base64State))
        return false;

    int slotId = 0;
    {
        const juce::ScopedLock graphLock(mainProcessorGraph->getCallbackLock());
        if (const auto* slot = findDesiredStageSlot(desiredMasterStageSpec, fxIndex))
            slotId = slot->slotId;
    }
    if (slotId == 0)
        return false;

    const auto activeStage = std::atomic_load_explicit(
        &realtimeMasterFXSnapshot, std::memory_order_acquire);
    const auto* activeSlot = findActiveStageSlot(activeStage, slotId);
    if (activeSlot == nullptr || activeSlot->processor == nullptr)
        return false;
    const auto processorOwner = activeSlot->processor;
    auto* processor = processorOwner.get();

    const int latencyBefore = processor->getLatencySamples();
    bool restored = false;
    // The rack asks for its publication lease only after all expensive model / IR
    // preparation is complete. It hands back only the lease associated with the
    // host configuration that actually published; a stale-configuration retry
    // releases its lease before re-preparing. Retain the successful lease until the
    // matching desired stage state has been persisted, so a newer request cannot
    // land between audible publication and persistence.
    std::shared_ptr<void> publicationLease;
    if (auto* rack = dynamic_cast<S13NAMRack*>(processor))
    {
        restored = rack->restoreProjectStateInformation(
            stateData.getData(),
            static_cast<int>(stateData.getSize()),
            publicationLeaseFactory,
            &publicationLease);
    }
    else
    {
        if (publicationLeaseFactory)
        {
            publicationLease = publicationLeaseFactory();
            if (! publicationLease)
                return false;
        }
        const juce::ScopedLock processorLock(processor->getCallbackLock());
        processor->setStateInformation(stateData.getData(), static_cast<int>(stateData.getSize()));
        restored = true;
    }
    if (! restored)
        return false;

    const auto serializedState = serialiseProcessorStateToBase64(processor);
    {
        const juce::ScopedLock graphLock(mainProcessorGraph->getCallbackLock());
        auto* desiredSlot = findDesiredStageSlot(desiredMasterStageSpec, fxIndex);
        if (desiredSlot == nullptr || desiredSlot->slotId != slotId)
            return false;
        desiredSlot->serializedState = serializedState;
    }
    publicationLease.reset();

    if (processor->getLatencySamples() != latencyBefore)
        recalculatePDC();

    juce::Logger::writeToLog("AudioEngine: Restored master plugin state for FX " + juce::String(fxIndex));
    return true;
}

//==============================================================================
// FFmpeg Helpers

juce::File AudioEngine::findFFmpegExe() const
{
    // Search for ffmpeg.exe in common locations relative to the executable
    auto exeDir = juce::File::getSpecialLocation(juce::File::currentExecutableFile).getParentDirectory();

    // 1. Same directory as executable
    auto ffmpeg = exeDir.getChildFile("ffmpeg.exe");
    if (ffmpeg.existsAsFile()) return ffmpeg;

    // 2. tools/ subdirectory
    ffmpeg = exeDir.getChildFile("tools").getChildFile("ffmpeg.exe");
    if (ffmpeg.existsAsFile()) return ffmpeg;

    // 3. ../tools/ (one level up)
    ffmpeg = exeDir.getParentDirectory().getChildFile("tools").getChildFile("ffmpeg.exe");
    if (ffmpeg.existsAsFile()) return ffmpeg;

    // 4. ../../tools/ (two levels up, for build/Studio13_artefacts/Release/)
    ffmpeg = exeDir.getParentDirectory().getParentDirectory().getChildFile("tools").getChildFile("ffmpeg.exe");
    if (ffmpeg.existsAsFile()) return ffmpeg;

    // 5. ../../../tools/ (three levels up, for deeper build paths)
    ffmpeg = exeDir.getParentDirectory().getParentDirectory().getParentDirectory().getChildFile("tools").getChildFile("ffmpeg.exe");
    if (ffmpeg.existsAsFile()) return ffmpeg;

    return juce::File(); // Not found
}

bool AudioEngine::convertWithFFmpeg(const juce::File& inputFile, const juce::File& outputFile,
                                     const juce::String& format, double targetSampleRate, int quality,
                                     int bitDepth, int numChannels) const
{
    auto ffmpeg = findFFmpegExe();
    if (!ffmpeg.existsAsFile())
    {
        logToDisk("convertWithFFmpeg: FAIL - ffmpeg.exe not found");
        return false;
    }

    // Build ffmpeg command
    juce::StringArray args;
    args.add(ffmpeg.getFullPathName());
    args.add("-y");                                // Overwrite output
    args.add("-i");
    args.add(inputFile.getFullPathName());         // Input file
    args.add("-map");
    args.add("0:a:0");
    args.add("-vn");
    args.add("-sn");
    args.add("-dn");

    juce::String formatLower = format.toLowerCase();
    double outputSampleRate = targetSampleRate;
    if (formatLower == "mp3" && outputSampleRate > 48000.0)
    {
        logToDisk("convertWithFFmpeg: MP3 does not support " + juce::String(outputSampleRate)
                  + " Hz; using 48000 Hz for MP3 output");
        outputSampleRate = 48000.0;
    }

    // Sample rate conversion (if target differs from source)
    if (outputSampleRate > 0)
    {
        args.add("-ar");
        args.add(juce::String((int)outputSampleRate));
    }
    if (numChannels == 1 || numChannels == 2)
    {
        args.add("-ac");
        args.add(juce::String(numChannels));
    }

    if (formatLower == "mp3")
    {
        args.add("-codec:a");
        args.add("libmp3lame");
        // quality = bitrate in kbps (128, 192, 256, 320)
        int bitrate = (quality > 0) ? quality : 320;
        args.add("-b:a");
        args.add(juce::String(bitrate) + "k");
    }
    else if (formatLower == "ogg")
    {
        args.add("-codec:a");
        args.add("libvorbis");
        // quality = vorbis quality level (0-10, default 6)
        int q = (quality > 0) ? quality : 6;
        args.add("-q:a");
        args.add(juce::String(q));
    }
    else if (formatLower == "wav")
    {
        args.add("-codec:a");
        args.add(bitDepth == 32 ? "pcm_f32le" : (bitDepth == 16 ? "pcm_s16le" : "pcm_s24le"));
    }
    else if (formatLower == "aiff" || formatLower == "aif")
    {
        args.add("-codec:a");
        args.add(bitDepth == 32 ? "pcm_f32be" : (bitDepth == 16 ? "pcm_s16be" : "pcm_s24be"));
    }
    else if (formatLower == "flac")
    {
        const int flacBitDepth = bitDepth >= 24 ? 24 : 16;
        args.add("-codec:a");
        args.add("flac");
        args.add("-sample_fmt");
        args.add(flacBitDepth == 24 ? "s32" : "s16");
        if (flacBitDepth == 24)
        {
            args.add("-bits_per_raw_sample");
            args.add("24");
        }
    }
    else
    {
        // WAV/AIFF/FLAC sample rate conversion only — keep format as-is
        // ffmpeg auto-detects output format from extension
    }

    args.add(outputFile.getFullPathName());        // Output file

    logToDisk("convertWithFFmpeg: Running: " + args.joinIntoString(" "));

    // Run ffmpeg as child process
    juce::ChildProcess process;
    if (!process.start(args))
    {
        logToDisk("convertWithFFmpeg: FAIL - could not start ffmpeg process");
        return false;
    }

    // Wait for completion (up to 5 minutes for large files)
    if (!process.waitForProcessToFinish(300000))
    {
        logToDisk("convertWithFFmpeg: FAIL - ffmpeg timed out after 5 minutes");
        process.kill();
        return false;
    }

    int exitCode = process.getExitCode();
    if (exitCode != 0)
    {
        juce::String errOutput = process.readAllProcessOutput();
        logToDisk("convertWithFFmpeg: FAIL - ffmpeg exit code " + juce::String(exitCode) + " output: " + errOutput);
        return false;
    }

    if (!outputFile.existsAsFile())
    {
        logToDisk("convertWithFFmpeg: FAIL - output file not created");
        return false;
    }

    logToDisk("convertWithFFmpeg: SUCCESS - " + outputFile.getFullPathName() +
              " (" + juce::String(outputFile.getSize() / 1024) + " KB)");
    return true;
}

//==============================================================================
// Offline Render/Export

bool AudioEngine::renderProject(const juce::String& source, double startTime, double endTime,
                                const juce::String& filePath, const juce::String& format,
                                double renderSampleRate, int bitDepth, int numChannels,
                                bool normalize, bool addTail, double tailLengthMs,
                                bool includeMetronome)
{
    const juce::ScopedLock offlineRenderTransaction(offlineRenderTransactionLock);
    logToDisk("renderProject: START - file=" + filePath + " format=" + format +
              " range=" + juce::String(startTime) + "-" + juce::String(endTime) +
              " sr=" + juce::String(renderSampleRate) + " bits=" + juce::String(bitDepth) +
              " ch=" + juce::String(numChannels) +
              " normalize=" + juce::String(normalize ? "true" : "false") +
              " addTail=" + juce::String(addTail ? "true" : "false") +
              " tailMs=" + juce::String(tailLengthMs) +
              " includeMetronome=" + juce::String(includeMetronome ? "true" : "false"));

    // ========== 1. Validate inputs ==========
    if (endTime <= startTime)
    {
        logToDisk("renderProject: FAIL - endTime (" + juce::String(endTime) +
                  ") <= startTime (" + juce::String(startTime) + ")");
        return false;
    }
    // Use requested sample rate for render if provided, otherwise fall back to device rate.
    // PlaybackEngine::fillTrackBuffer() handles per-file SR conversion automatically,
    // so rendering at a different rate than the device is fully supported.
    double requestedOutputSampleRate = (renderSampleRate > 0) ? renderSampleRate : currentSampleRate;
    if (requestedOutputSampleRate <= 0) requestedOutputSampleRate = 44100.0;
    double actualSampleRate = requestedOutputSampleRate;
    if (bitDepth != 16 && bitDepth != 24 && bitDepth != 32) bitDepth = 24;
    if (numChannels < 1 || numChannels > 2) numChannels = 2;

    // Determine if we need post-processing (lossy encoding only — SR conversion
    // is now handled natively by rendering at the target rate)
    juce::String formatLower = format.toLowerCase();
    bool isLossyFormat = (formatLower == "mp3" || formatLower == "ogg");
    bool needsFFmpegPostProcess = isLossyFormat;

    // For lossy formats, bitDepth holds codec quality:
    //   MP3: bitrate in kbps (128, 192, 256, 320)
    //   OGG: quality level (1-10)
    int codecQuality = isLossyFormat ? bitDepth : 0;
    if (isLossyFormat) bitDepth = 24; // Render intermediate WAV at 24-bit

    // Parse stem track filter from source (e.g., "stem:trackId123")
    juce::String stemTrackId;
    bool isStemRender = source.startsWith("stem:");
    if (isStemRender)
        stemTrackId = source.substring(5); // After "stem:"

    const bool canUseFFmpegSampleRatePostProcess =
        isLossyFormat
        || formatLower == "wav"
        || formatLower == "aiff"
        || formatLower == "aif"
        || formatLower == "flac";

    if (isLossyFormat)
        logToDisk("renderProject: Lossy format=" + formatLower + " codecQuality=" + juce::String(codecQuality));
    if (isStemRender)
        logToDisk("renderProject: Stem render for trackId=" + stemTrackId);

    // ========== 2. Stop real-time playback and block audio callback ==========
    bool wasPlaying = isPlaying.load();
    bool wasRecording = isRecordMode.load();
    if (wasPlaying) isPlaying = false;
    if (wasRecording) isRecordMode = false;
    isRendering = true;  // Block audio callback from processing FX plugins
    juce::Thread::sleep(100); // Let audio callback finish current block

    // Exports must be sourced from baked clip files only.  Live pitch previews,
    // scrub loops, and rendered preview segments are UI audition routes; letting
    // them survive into the render snapshot can add bursts even for no-op renders.
    playbackEngine.clearAllPitchPreviewRoutes(juce::String());

    // ========== 3. Snapshot clip data ==========
    auto clipSnapshot = playbackEngine.getClipSnapshot();
    auto renderedPreviewSegmentSnapshot = playbackEngine.getRenderedPreviewSegmentSnapshot();
    int staleRenderedPitchSegmentsDropped = 0;
    const bool includePitchPreviewSegmentsInRender = getPitchEnvFlag ("OPENSTUDIO_RENDER_INCLUDE_PITCH_PREVIEW_SEGMENTS", false);
    if (! includePitchPreviewSegmentsInRender && ! renderedPreviewSegmentSnapshot.empty())
    {
        for (const auto& entry : renderedPreviewSegmentSnapshot)
            staleRenderedPitchSegmentsDropped += static_cast<int>(entry.second.size());
        renderedPreviewSegmentSnapshot.clear();
    }
    for (const auto& clip : clipSnapshot)
    {
        if (clip.clipId.isEmpty())
            continue;

        const bool usingCorrectedSource = clip.originalAudioFile.existsAsFile()
            && clip.audioFile.existsAsFile()
            && clip.audioFile != clip.originalAudioFile;
        if (! usingCorrectedSource)
            continue;

        auto segmentIt = renderedPreviewSegmentSnapshot.find(clip.clipId);
        if (segmentIt != renderedPreviewSegmentSnapshot.end())
        {
            staleRenderedPitchSegmentsDropped += static_cast<int>(segmentIt->second.size());
            renderedPreviewSegmentSnapshot.erase(segmentIt);
        }
    }
    logToDisk("renderProject: Clip snapshot has " + juce::String((int)clipSnapshot.size()) + " clips");
    logToDisk("renderProject: Rendered pitch segment snapshot has "
              + juce::String((int)renderedPreviewSegmentSnapshot.size()) + " clips");
    if (staleRenderedPitchSegmentsDropped > 0)
        logToDisk("renderProject: Dropped " + juce::String(staleRenderedPitchSegmentsDropped)
                  + " rendered pitch preview segment(s) before export"
                  + juce::String(includePitchPreviewSegmentsInRender ? " because corrected source files are active"
                                                                     : " because exports must use baked/original clip sources"));

    if (clipSnapshot.empty())
    {
        logToDisk("renderProject: WARNING - No clips in playback engine! Render will be silent.");
    }

    // Log each clip for debugging
    for (size_t i = 0; i < clipSnapshot.size(); ++i)
    {
        const auto& clip = clipSnapshot[i];
        logToDisk("  Clip " + juce::String((int)i) + ": track=" + clip.trackId +
                  " file=" + clip.audioFile.getFileName() +
                  " start=" + juce::String(clip.startTime) +
                  " dur=" + juce::String(clip.duration) +
                  " offset=" + juce::String(clip.offset) +
                  " active=" + juce::String(clip.isActive ? "true" : "false"));
    }

    // ========== 4. Snapshot track params ==========
    struct TrackSnapshot {
        juce::String id;
        float volumeDB;
        float pan;
        bool muted;
        bool soloed;
        int inputFxCount = 0;
        int trackFxCount = 0;
        int sendCount = 0;
        int sidechainSourceCount = 0;
        bool isInstrumentTrack = false;
        bool hasInstrument = false;
        bool hasARA = false;
        bool masterSendEnabled = true;
        bool hasTrackAutomation = false;
        bool hasPluginAutomation = false;
        bool requiresFullRender = false;
    };
    std::vector<TrackSnapshot> trackSnapshots;
    std::map<juce::String, TrackSnapshot> trackSnapshotById;
    bool anySoloed = false;
    auto automationIsActive = [] (const AutomationList& automation)
    {
        return automation.shouldPlaybackForRead() && automation.getNumPoints() > 0;
    };
    {
        const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
        for (const auto& trackId : trackOrder)
        {
            auto it = trackMap.find(trackId);
            if (it == trackMap.end() || !it->second) continue;
            auto* track = it->second;
            TrackSnapshot snap;
            snap.id = trackId;
            snap.volumeDB = track->getVolume();
            snap.pan = track->getPan();
            snap.muted = track->getMute();
            snap.soloed = track->getSolo();
            snap.inputFxCount = track->getNumInputFX();
            snap.trackFxCount = track->getNumTrackFX();
            snap.isInstrumentTrack = track->getTrackType() == TrackType::Instrument;
            snap.hasInstrument = track->getInstrument() != nullptr;
            snap.hasARA = track->hasActiveARA();
            snap.masterSendEnabled = track->getMasterSendEnabled();
            snap.sendCount = static_cast<int>(track->getRealtimeSendSnapshot().size());
            snap.sidechainSourceCount = static_cast<int>(track->getSidechainSourceSnapshot().size());
            snap.hasPluginAutomation = track->hasPluginAutomation();
            snap.hasTrackAutomation =
                automationIsActive(track->getVolumeAutomation())
                || automationIsActive(track->getPanAutomation())
                || automationIsActive(track->getWidthAutomation())
                || automationIsActive(track->getPreFXVolumeAutomation())
                || automationIsActive(track->getPreFXPanAutomation())
                || automationIsActive(track->getPreFXWidthAutomation())
                || automationIsActive(track->getTrimVolumeAutomation())
                || automationIsActive(track->getMuteAutomation())
                || snap.hasPluginAutomation
                || track->hasMIDIAutomation();
            snap.requiresFullRender =
                snap.inputFxCount > 0
                || snap.trackFxCount > 0
                || snap.isInstrumentTrack
                || snap.hasInstrument
                || snap.hasARA
                || snap.sendCount > 0
                || snap.sidechainSourceCount > 0
                || snap.hasTrackAutomation
                || (!isStemRender && !snap.masterSendEnabled);
            if (snap.soloed) anySoloed = true;
            trackSnapshots.push_back(snap);
            trackSnapshotById[snap.id] = snap;
            logToDisk("  Track " + trackId + ": vol=" + juce::String(snap.volumeDB) +
                      "dB pan=" + juce::String(snap.pan) +
                      " mute=" + juce::String(snap.muted ? "true" : "false") +
                      " solo=" + juce::String(snap.soloed ? "true" : "false") +
                      " instrumentTrack=" + juce::String(snap.isInstrumentTrack ? "true" : "false") +
                      " fx=" + juce::String(snap.inputFxCount + snap.trackFxCount) +
                      " sends=" + juce::String(snap.sendCount) +
                      " sidechains=" + juce::String(snap.sidechainSourceCount) +
                      " automation=" + juce::String(snap.hasTrackAutomation ? "true" : "false"));
        }
    }

    logToDisk("renderProject: " + juce::String((int)trackSnapshots.size()) + " tracks, anySoloed=" + juce::String(anySoloed ? "true" : "false"));

    if (canUseFFmpegSampleRatePostProcess)
    {
        double includedClipSampleRate = 0.0;
        bool includedClipsHaveSingleSampleRate = false;
        bool includedClipSampleRateMismatch = false;
        juce::AudioFormatManager sourceRateFormatManager;
        sourceRateFormatManager.registerBasicFormats();

        for (const auto& clip : clipSnapshot)
        {
            if (! clip.isActive)
                continue;

            auto trackIt = trackSnapshotById.find(clip.trackId);
            if (trackIt == trackSnapshotById.end())
                continue;

            const auto& snap = trackIt->second;
            if (isStemRender && snap.id != stemTrackId)
                continue;
            if (! isStemRender && snap.muted)
                continue;
            if (! isStemRender && anySoloed && ! snap.soloed)
                continue;

            std::unique_ptr<juce::AudioFormatReader> reader(sourceRateFormatManager.createReaderFor(clip.audioFile));
            if (! reader || reader->sampleRate <= 0.0)
                continue;

            if (! includedClipsHaveSingleSampleRate)
            {
                includedClipSampleRate = reader->sampleRate;
                includedClipsHaveSingleSampleRate = true;
            }
            else if (std::abs(includedClipSampleRate - reader->sampleRate) > 1.0)
            {
                includedClipSampleRateMismatch = true;
                break;
            }
        }

        if (includedClipsHaveSingleSampleRate
            && ! includedClipSampleRateMismatch
            && std::abs(includedClipSampleRate - requestedOutputSampleRate) > 1.0
            && includedClipSampleRate <= 192000.0)
        {
            logToDisk("renderProject: intermediate render sample rate set from "
                      + juce::String(actualSampleRate) + " to source rate "
                      + juce::String(includedClipSampleRate)
                      + " so FFmpeg handles final SRC to "
                      + juce::String(requestedOutputSampleRate));
            actualSampleRate = includedClipSampleRate;
            needsFFmpegPostProcess = true;
        }
    }

    logToDisk("renderProject: Using actualSampleRate=" + juce::String(actualSampleRate) +
              (std::abs(actualSampleRate - requestedOutputSampleRate) > 1.0
                  ? " (ffmpeg intermediate; requested output rate " + juce::String(requestedOutputSampleRate) + ")"
                  : (actualSampleRate != currentSampleRate ? " (differs from device rate " + juce::String(currentSampleRate) + ")" : " (device rate)")));

    struct ScopedTrackMuteBypass
    {
        TrackProcessor* track = nullptr;
        ~ScopedTrackMuteBypass()
        {
            if (track != nullptr)
                track->setIgnoreStaticMuteForProcessing(false);
        }
    } stemMuteBypass;

    if (isStemRender)
    {
        auto trackIt = trackMap.find(stemTrackId);
        if (trackIt != trackMap.end() && trackIt->second != nullptr)
        {
            trackIt->second->setIgnoreStaticMuteForProcessing(true);
            stemMuteBypass.track = trackIt->second;
        }
    }

    // ========== 5. Create format writer ==========
    // For lossy formats (mp3/ogg) or sample rate conversion, render to temp WAV first
    juce::File outputFile(filePath);
    juce::File renderFile = outputFile; // File we actually write to (may be temp WAV)

    if (needsFFmpegPostProcess)
    {
        // Create temp WAV file next to the output
        renderFile = outputFile.getParentDirectory().getChildFile(
            outputFile.getFileNameWithoutExtension() + "_temp_render.wav");
    }

    std::unique_ptr<juce::AudioFormat> audioFormat;
    juce::String renderFormatLower = needsFFmpegPostProcess ? "wav" : formatLower;

    if (renderFormatLower == "wav")
        audioFormat = std::make_unique<juce::WavAudioFormat>();
    else if (renderFormatLower == "aiff" || renderFormatLower == "aif")
        audioFormat = std::make_unique<juce::AiffAudioFormat>();
    else if (renderFormatLower == "flac")
    {
        audioFormat = std::make_unique<juce::FlacAudioFormat>();
        if (bitDepth > 24) bitDepth = 24; // FLAC max 24-bit
    }
    else
    {
        logToDisk("renderProject: FAIL - unsupported format: " + format);
        isRendering = false;
        return false;
    }

    renderFile.getParentDirectory().createDirectory();
    if (renderFile.existsAsFile())
        renderFile.deleteFile();
    if (outputFile.existsAsFile())
        outputFile.deleteFile();

    auto fileStream = std::make_unique<juce::FileOutputStream>(renderFile);
    if (fileStream->failedToOpen())
    {
        logToDisk("renderProject: FAIL - could not open output file: " + renderFile.getFullPathName());
        isRendering = false;
        return false;
    }

    // Determine writer channels (always render in stereo internally, downmix to mono if needed)
    int writerChannels = numChannels;

    std::unique_ptr<juce::AudioFormatWriter> writer(
        audioFormat->createWriterFor(fileStream.get(),
                                     actualSampleRate,
                                     writerChannels,
                                     bitDepth,
                                     {}, // metadata
                                     0)); // quality
    if (!writer)
    {
        logToDisk("renderProject: FAIL - could not create writer (sr=" +
                  juce::String(actualSampleRate) + " bits=" + juce::String(bitDepth) +
                  " ch=" + juce::String(writerChannels) + ")");
        isRendering = false;
        return false;
    }
    fileStream.release(); // Writer owns the stream now

    // ========== 6. Establish the requested source range ==========
    const double sourceDuration = endTime - startTime;
    const juce::int64 sourceSamples = juce::jmax<juce::int64>(
        1,
        nonNegativeSecondsToSamples(sourceDuration, actualSampleRate));
    double tailSeconds = addTail ? juce::jmax(0.0, tailLengthMs * 0.001) : 0.0;
    double totalDuration = sourceDuration + tailSeconds;
    juce::int64 totalSamples = sourceSamples
        + nonNegativeSecondsToSamples(tailSeconds, actualSampleRate);
    juce::int64 processingTotalSamples = totalSamples;
    OfflineRenderPlan offlineRenderPlan;
    const int blockSize = 2048;  // Larger block size for faster offline rendering

    const bool renderChainDebugEnabled = getPitchEnvFlag ("OPENSTUDIO_AUDIO_CHAIN_DEBUG", false)
        || getPitchEnvFlag ("OPENSTUDIO_RENDER_CHAIN_DEBUG", false);
    const double renderChainDebugMaxSec = juce::jlimit (0.25, 600.0,
        static_cast<double> (getPitchEnvFloat ("OPENSTUDIO_AUDIO_CHAIN_DEBUG_MAX_SEC", 12.0f)));
    int renderChainCaptureSamples = 0;
    const auto renderChainDebugDirEnv = juce::SystemStats::getEnvironmentVariable ("OPENSTUDIO_AUDIO_CHAIN_DEBUG_DIR", {}).trim();
    const juce::File renderChainDebugDir = renderChainDebugDirEnv.isNotEmpty()
        ? juce::File (renderChainDebugDirEnv)
        : outputFile.getSiblingFile (outputFile.getFileNameWithoutExtension() + "_signal_chain_debug");
    juce::AudioBuffer<float> chainPlaybackBlock;
    juce::AudioBuffer<float> chainTrackPostBlock;
    juce::AudioBuffer<float> chainMasterPreBlock;
    juce::AudioBuffer<float> chainMasterPostBlock;
    juce::AudioBuffer<float> chainWriterInputBlock;
    juce::AudioBuffer<float> chainPlaybackTap;
    juce::AudioBuffer<float> chainTrackPostTap;
    juce::AudioBuffer<float> chainMasterPreTap;
    juce::AudioBuffer<float> chainMasterPostTap;
    juce::AudioBuffer<float> chainWriterInputTap;
    juce::Array<juce::var> renderChainBlockReports;

    // ========== 6b. Save plugin state & prepare plugins for offline rendering ==========
    // Plugins were prepared for the device's buffer size (e.g. 128/256). The render
    // uses 512-sample blocks. We must re-prepare all FX plugins with the render block
    // size, otherwise plugins like Amplitube overflow internal buffers → noise/crash.
    // We also reset() to clear stale state from real-time playback.

    // Collect all FX processors that will be used during render
    struct PluginStateBackup {
        juce::AudioProcessor* processor;
        juce::MemoryBlock savedState;
        bool preparedByTrack = false;
    };
    std::vector<PluginStateBackup> pluginBackups;
    std::vector<TrackProcessor*> renderPreparedTracks;

    auto backupProcessorForRender = [&](juce::AudioProcessor* proc, bool preparedByTrack = false) {
        if (!proc) return;
        const auto alreadyBackedUp = std::find_if(pluginBackups.begin(), pluginBackups.end(),
            [proc](const PluginStateBackup& backup) { return backup.processor == proc; });
        if (alreadyBackedUp != pluginBackups.end())
        {
            alreadyBackedUp->preparedByTrack = alreadyBackedUp->preparedByTrack || preparedByTrack;
            return;
        }

        // Save current state
        PluginStateBackup backup;
        backup.processor = proc;
        backup.preparedByTrack = preparedByTrack;
        proc->getStateInformation(backup.savedState);
        pluginBackups.push_back(std::move(backup));
    };

    // Lambda to save state, prepare, and reset a processor for render.
    auto prepareProcessorForRender = [&](juce::AudioProcessor* proc) {
        backupProcessorForRender(proc);
        if (!proc) return;
        prepareHostedProcessorForPrecision(proc, actualSampleRate, blockSize, processingPrecisionMode);
        proc->reset();
    };

    auto restorePreparedTracksForRealtime = [&]()
    {
        const double realtimeSampleRate = currentSampleRate > 0.0 ? currentSampleRate : actualSampleRate;
        const int realtimeBlockSize = currentBlockSize > 0 ? currentBlockSize : 512;

        // Restore NAM scalar controls before TrackProcessor re-prepares its
        // children, so smoothers/filter targets are initialized from the live
        // pre-render state without touching model or IR resources.
        for (auto& backup : pluginBackups)
        {
            if (auto* rack = dynamic_cast<S13NAMRack*>(backup.processor))
            {
                rack->restoreRenderPassStateInformation(backup.savedState.getData(),
                                                        static_cast<int>(backup.savedState.getSize()));
            }
        }

        for (auto* track : renderPreparedTracks)
        {
            if (track != nullptr)
                track->prepareToPlay(realtimeSampleRate, realtimeBlockSize);
        }

        for (auto& backup : pluginBackups)
        {
            if (backup.processor)
            {
                if (! backup.preparedByTrack)
                    backup.processor->prepareToPlay(realtimeSampleRate, juce::jmax(realtimeBlockSize, 512));

                // Rendering does not mutate NAM tone/resource identity. A full
                // state restore would re-probe model files and re-submit the IR
                // asynchronously just before live playback resumes.
                if (auto* rack = dynamic_cast<S13NAMRack*>(backup.processor))
                {
                    const bool restored = rack->restoreRenderPassStateInformation(
                        backup.savedState.getData(), static_cast<int>(backup.savedState.getSize()));
                    if (! restored)
                        logToDisk("renderProject: NAM render-pass scalar restore failed");
                }
                else
                {
                    backup.processor->setStateInformation(backup.savedState.getData(),
                                                           (int)backup.savedState.getSize());
                }
                backup.processor->reset();
            }
        }

        recalculatePDC();
    };

    // Prepare complete track processors for the offline block size. This is not
    // just plugin sample-rate setup: TrackProcessor owns expanded FX buffers,
    // fallback-instrument state, channel strip EQ, PDC, and send buffers. If it
    // remains sized for the realtime block while render uses 2048 samples, stem
    // renders can turn into crackle/low garbage.
    for (const auto& snap : trackSnapshots)
    {
        auto it = trackMap.find(snap.id);
        if (it == trackMap.end() || !it->second) continue;
        auto* track = it->second;
        for (int fx = 0; fx < track->getNumInputFX(); ++fx)
            backupProcessorForRender(track->getInputFXProcessor(fx), true);
        for (int fx = 0; fx < track->getNumTrackFX(); ++fx)
            backupProcessorForRender(track->getTrackFXProcessor(fx), true);
        backupProcessorForRender(track->getInstrument(), true);
        track->prepareToPlay(actualSampleRate, blockSize);
        renderPreparedTracks.push_back(track);
    }
    recalculatePDC();

    DesiredFXStageSpec renderMasterSpec;
    {
        const juce::ScopedLock stageLock(mainProcessorGraph->getCallbackLock());
        renderMasterSpec = desiredMasterStageSpec;
    }
    syncStageSpecStateFromActive(renderMasterSpec, std::atomic_load_explicit(&realtimeMasterFXSnapshot, std::memory_order_acquire));

    juce::String renderStageError;
    auto renderMasterStage = buildActiveFXStage(renderMasterSpec, actualSampleRate, blockSize, processingPrecisionMode, false, renderStageError);
    if (!renderMasterStage && !renderMasterSpec.slots.empty())
    {
        logToDisk("renderProject: FAIL - could not build master stage: " + renderStageError);
        restorePreparedTracksForRealtime();
        isRendering = false;
        return false;
    }

    if (renderMasterStage)
    {
        for (const auto& slot : renderMasterStage->slots)
            prepareProcessorForRender(slot.processor.get());
    }

    logToDisk("renderProject: Saved & prepared " + juce::String((int)pluginBackups.size()) + " FX plugins for render");

    int activeMasterFxCount = 0;
    if (renderMasterStage)
    {
        for (const auto& slot : renderMasterStage->slots)
            if (!slot.bypassed && slot.processor)
                ++activeMasterFxCount;
    }

    const bool hasMasterAutomation = !isStemRender
        && (automationIsActive(masterVolumeAutomation) || automationIsActive(masterPanAutomation));

    bool includedTracksCanUseSimplePath = true;
    for (const auto& snap : trackSnapshots)
    {
        if (isStemRender && snap.id != stemTrackId)
            continue;
        if (!isStemRender && snap.muted)
            continue;
        if (!isStemRender && anySoloed && !snap.soloed)
            continue;

        if (snap.requiresFullRender)
        {
            includedTracksCanUseSimplePath = false;
            break;
        }
    }

    const bool useSimpleNoFxRenderLoop =
        includedTracksCanUseSimplePath
        && activeMasterFxCount == 0
        && !hasMasterAutomation;

    const auto trackIsIncludedInRender = [&] (const TrackSnapshot& snap)
    {
        if (isStemRender)
            return snap.id == stemTrackId;
        if (snap.muted)
            return false;
        return ! anySoloed || snap.soloed;
    };

    bool hasIncludedTrack = false;
    double declaredTrackTailSeconds = 0.0;
    for (const auto& snap : trackSnapshots)
    {
        if (! trackIsIncludedInRender(snap))
            continue;

        auto trackIt = trackMap.find(snap.id);
        if (trackIt == trackMap.end() || trackIt->second == nullptr)
            continue;

        hasIncludedTrack = true;
        const double trackTail = trackIt->second->getOfflineRenderTailLengthSeconds();
        if (std::isfinite(trackTail) && trackTail > 0.0)
            declaredTrackTailSeconds = juce::jmax(declaredTrackTailSeconds, trackTail);
    }

    // TrackProcessor applies PDC before each serial plugin chain. recalculatePDC()
    // aligns every processed track to the largest chain latency in the project,
    // including tracks excluded by solo/mute, so the export trim must use that
    // same common delay whenever the full TrackProcessor path is active.
    int alignedTrackLatencySamples = 0;
    if (! useSimpleNoFxRenderLoop && hasIncludedTrack)
    {
        for (const auto& [trackId, track] : trackMap)
        {
            juce::ignoreUnused(trackId);
            if (track != nullptr)
                alignedTrackLatencySamples = juce::jmax(alignedTrackLatencySamples,
                                                        track->getChainLatency());
        }
    }

    int masterLatencySamples = 0;
    double declaredMasterTailSeconds = 0.0;
    if (! isStemRender && renderMasterStage)
    {
        for (const auto& slot : renderMasterStage->slots)
        {
            if (slot.bypassed || slot.processor == nullptr)
                continue;

            const int slotLatencySamples = juce::jmax(0, slot.processor->getLatencySamples());
            masterLatencySamples = masterLatencySamples > std::numeric_limits<int>::max() - slotLatencySamples
                ? std::numeric_limits<int>::max()
                : masterLatencySamples + slotLatencySamples;
            const double slotTail = slot.processor->getTailLengthSeconds();
            if (std::isfinite(slotTail) && slotTail > 0.0)
                declaredMasterTailSeconds += slotTail;
        }
    }

    const int totalRenderLatencySamples = alignedTrackLatencySamples > std::numeric_limits<int>::max() - masterLatencySamples
        ? std::numeric_limits<int>::max()
        : alignedTrackLatencySamples + masterLatencySamples;
    const double declaredEffectTailSeconds = declaredTrackTailSeconds + declaredMasterTailSeconds;
    offlineRenderPlan = makeOfflineRenderPlan(sourceSamples,
                                              actualSampleRate,
                                              addTail,
                                              tailLengthMs * 0.001,
                                              declaredEffectTailSeconds,
                                              totalRenderLatencySamples);
    tailSeconds = offlineRenderPlan.effectiveTailSeconds;
    totalDuration = static_cast<double>(offlineRenderPlan.outputSamples) / actualSampleRate;
    totalSamples = offlineRenderPlan.outputSamples;
    processingTotalSamples = offlineRenderPlan.processingSamples;

    logToDisk("renderProject: outputDuration=" + juce::String(totalDuration)
              + "s sourceSamples=" + juce::String(sourceSamples)
              + " effectTailSamples=" + juce::String(offlineRenderPlan.effectTailSamples)
              + " outputSamples=" + juce::String(totalSamples)
              + " processingSamples=" + juce::String(processingTotalSamples)
              + " alignedTrackLatency=" + juce::String(alignedTrackLatencySamples)
              + " masterLatency=" + juce::String(masterLatencySamples)
              + " declaredTailSec=" + juce::String(declaredEffectTailSeconds, 6)
              + " effectiveTailSec=" + juce::String(tailSeconds, 6)
              + " blockSize=" + juce::String(blockSize));

    if (renderChainDebugEnabled)
    {
        renderChainCaptureSamples = static_cast<int>(std::min<juce::int64>(
            totalSamples,
            static_cast<juce::int64>(std::ceil(renderChainDebugMaxSec * actualSampleRate))));
        renderChainDebugDir.createDirectory();
        chainPlaybackBlock.setSize(2, blockSize);
        chainTrackPostBlock.setSize(2, blockSize);
        chainMasterPreBlock.setSize(2, blockSize);
        chainMasterPostBlock.setSize(2, blockSize);
        chainWriterInputBlock.setSize(2, blockSize);
        if (renderChainCaptureSamples > 0)
        {
            chainPlaybackTap.setSize(2, renderChainCaptureSamples);
            chainTrackPostTap.setSize(2, renderChainCaptureSamples);
            chainMasterPreTap.setSize(2, renderChainCaptureSamples);
            chainMasterPostTap.setSize(2, renderChainCaptureSamples);
            chainWriterInputTap.setSize(2, renderChainCaptureSamples);
            chainPlaybackTap.clear();
            chainTrackPostTap.clear();
            chainMasterPreTap.clear();
            chainMasterPostTap.clear();
            chainWriterInputTap.clear();
        }

        logToDisk("renderProject: signal-chain debug enabled dir=" + renderChainDebugDir.getFullPathName()
                  + " captureSamples=" + juce::String(renderChainCaptureSamples)
                  + " maxSec=" + juce::String(renderChainDebugMaxSec, 2));
    }

    logToDisk("renderProject: renderLoopMode="
              + juce::String(useSimpleNoFxRenderLoop ? "simple_no_fx" : "full_realtime_snapshot")
              + " activeMasterFx=" + juce::String(activeMasterFxCount)
              + " masterAutomation=" + juce::String(hasMasterAutomation ? "true" : "false"));

    // ========== 7 & 8. Render loop (with optional 2-pass normalization) ==========
    int numPasses = normalize ? 2 : 1;
    float normGain = 1.0f;
    float peakLevel = 0.0f;

    // Dither state (0 = off, 1 = TPDF, 2 = noise-shaped)
    int ditherMode = pendingDitherMode_.load();
    pendingDitherMode_ = 0; // Reset for next render call
    juce::Random ditherRng;
    float ditherErrorState[2] = { 0.0f, 0.0f }; // Per-channel error feedback for noise shaping

    // Renders are silent with respect to the click by default.  Playback may
    // have the metronome enabled, but exports must opt in explicitly.
    bool renderMetronomeAudio = includeMetronome && metronome.isEnabled();
    const bool useRenderLagrangeSrc = getPitchEnvFlag("OPENSTUDIO_RENDER_USE_LAGRANGE_SRC", false);
    auto rtTracks = std::atomic_load_explicit(&realtimeTrackSnapshot, std::memory_order_acquire);

    struct ScopedAutomationReadOverride
    {
        std::vector<TrackProcessor*> tracks;
        ~ScopedAutomationReadOverride()
        {
            for (auto* track : tracks)
                if (track != nullptr)
                    track->setForceAutomationReadForProcessing(false);
        }
    } scopedAutomationReadOverride;

    for (auto const& [trackId, track] : trackMap)
    {
        juce::ignoreUnused(trackId);
        if (track != nullptr)
        {
            track->setForceAutomationReadForProcessing(true);
            scopedAutomationReadOverride.tracks.push_back(track);
        }
    }

    auto writeRenderRouteReport = [&]()
    {
        auto* root = new juce::DynamicObject();
        root->setProperty("schemaVersion", 1);
        root->setProperty("purpose", "manual_render_route_report");
        root->setProperty("source", source);
        root->setProperty("startTimeSec", startTime);
        root->setProperty("endTimeSec", endTime);
        root->setProperty("requestedOutputFile", outputFile.getFullPathName());
        root->setProperty("renderFile", renderFile.getFullPathName());
        root->setProperty("format", format);
        root->setProperty("requestedOutputSampleRate", requestedOutputSampleRate);
        root->setProperty("actualSampleRate", actualSampleRate);
        root->setProperty("ffmpegPostProcess", needsFFmpegPostProcess);
        root->setProperty("lossyIntermediateRender", isLossyFormat);
        root->setProperty("bitDepth", bitDepth);
        root->setProperty("channels", numChannels);
        root->setProperty("normalize", normalize);
        root->setProperty("addTail", addTail);
        root->setProperty("tailLengthMs", tailLengthMs);
        root->setProperty("declaredEffectTailSec", declaredEffectTailSeconds);
        root->setProperty("effectiveEffectTailSec", offlineRenderPlan.effectiveTailSeconds);
        root->setProperty("sourceSamples", static_cast<int64>(sourceSamples));
        root->setProperty("outputSamples", static_cast<int64>(totalSamples));
        root->setProperty("processingSamples", static_cast<int64>(processingTotalSamples));
        root->setProperty("alignedTrackLatencySamples", alignedTrackLatencySamples);
        root->setProperty("masterLatencySamples", masterLatencySamples);
        root->setProperty("trimmedStartupLatencySamples", totalRenderLatencySamples);
        root->setProperty("includeMetronome", includeMetronome);
        root->setProperty("renderMetronomeAudio", renderMetronomeAudio);
        root->setProperty("metronomeEnabledInProject", metronome.isEnabled());
        root->setProperty("renderPlaybackResampler", "shared_cubic_fractional");
        root->setProperty("renderPlaybackResamplerLegacyLagrangeRequested", useRenderLagrangeSrc);
        root->setProperty("isStemRender", isStemRender);
        root->setProperty("stemTrackId", stemTrackId);
        root->setProperty("clipCount", static_cast<int>(clipSnapshot.size()));
        root->setProperty("trackCount", static_cast<int>(trackSnapshots.size()));
        root->setProperty("anySoloed", anySoloed);
        root->setProperty("renderedPreviewSegmentClipCount", static_cast<int>(renderedPreviewSegmentSnapshot.size()));
        root->setProperty("renderedPitchSegmentsDroppedBeforeSnapshot", staleRenderedPitchSegmentsDropped);
        root->setProperty("activeMasterFxCount", activeMasterFxCount);
        root->setProperty("hasMasterAutomation", hasMasterAutomation);
        root->setProperty("renderLoopMode", useSimpleNoFxRenderLoop ? "simple_no_fx" : "full_realtime_snapshot");
        root->setProperty("writtenAt", juce::Time::getCurrentTime().toISO8601(true));

        juce::Array<juce::var> clipArray;
        juce::AudioFormatManager reportFormatManager;
        reportFormatManager.registerBasicFormats();
        for (const auto& clip : clipSnapshot)
        {
            auto* obj = new juce::DynamicObject();
            const bool usingCorrectedSource = clip.originalAudioFile.existsAsFile()
                && clip.audioFile.existsAsFile()
                && clip.audioFile != clip.originalAudioFile;
            obj->setProperty("clipId", clip.clipId);
            obj->setProperty("trackId", clip.trackId);
            obj->setProperty("audioFile", clip.audioFile.getFullPathName());
            obj->setProperty("originalAudioFile", clip.originalAudioFile.getFullPathName());
            obj->setProperty("startTime", clip.startTime);
            obj->setProperty("duration", clip.duration);
            obj->setProperty("offset", clip.offset);
            obj->setProperty("volumeDB", clip.volumeDB);
            obj->setProperty("fadeIn", clip.fadeIn);
            obj->setProperty("fadeOut", clip.fadeOut);
            obj->setProperty("active", clip.isActive);
            obj->setProperty("usingCorrectedSource", usingCorrectedSource);
            if (auto reader = std::unique_ptr<juce::AudioFormatReader>(reportFormatManager.createReaderFor(clip.audioFile)))
            {
                obj->setProperty("audioFileSampleRate", reader->sampleRate);
                obj->setProperty("audioFileChannels", static_cast<int>(reader->numChannels));
                obj->setProperty("audioFileLengthSamples", static_cast<int64>(reader->lengthInSamples));
            }
            clipArray.add(juce::var(obj));
        }
        root->setProperty("clips", juce::var(clipArray));

        juce::Array<juce::var> trackArray;
        for (const auto& snap : trackSnapshots)
        {
            auto* obj = new juce::DynamicObject();
            obj->setProperty("id", snap.id);
            obj->setProperty("volumeDB", snap.volumeDB);
            obj->setProperty("pan", snap.pan);
            obj->setProperty("muted", snap.muted);
            obj->setProperty("soloed", snap.soloed);
            obj->setProperty("inputFxCount", snap.inputFxCount);
            obj->setProperty("trackFxCount", snap.trackFxCount);
            obj->setProperty("isInstrumentTrack", snap.isInstrumentTrack);
            obj->setProperty("hasInstrument", snap.hasInstrument);
            obj->setProperty("hasARA", snap.hasARA);
            obj->setProperty("sendCount", snap.sendCount);
            obj->setProperty("sidechainSourceCount", snap.sidechainSourceCount);
            obj->setProperty("masterSendEnabled", snap.masterSendEnabled);
            obj->setProperty("hasTrackAutomation", snap.hasTrackAutomation);
            obj->setProperty("hasPluginAutomation", snap.hasPluginAutomation);
            obj->setProperty("requiresFullRender", snap.requiresFullRender);
            trackArray.add(juce::var(obj));
        }
        root->setProperty("tracks", juce::var(trackArray));

        const auto reportFile = outputFile.getSiblingFile(outputFile.getFileNameWithoutExtension() + "_render_route_report.json");
        reportFile.getParentDirectory().createDirectory();
        const bool wrote = reportFile.replaceWithText(juce::JSON::toString(juce::var(root), true));
        logToDisk("renderProject: route report=" + reportFile.getFullPathName()
                  + " wrote=" + juce::String(wrote ? "true" : "false"));
    };

    writeRenderRouteReport();

    auto buildRenderChainRouteTrace = [&] (const juce::String& trackId,
                                           double blockStartSec,
                                           int blockSamples) -> juce::var
    {
        juce::Array<juce::var> routes;
        const double blockEndSec = blockStartSec + static_cast<double> (blockSamples) / actualSampleRate;
        for (const auto& clip : clipSnapshot)
        {
            if (! clip.isActive || clip.trackId != trackId)
                continue;

            const double clipEndSec = clip.startTime + clip.duration;
            if (blockStartSec >= clipEndSec || blockEndSec <= clip.startTime)
                continue;

            const double blockMidSec = (std::max (blockStartSec, clip.startTime)
                + std::min (blockEndSec, clipEndSec)) * 0.5;
            const double clipTimeSec = blockMidSec - clip.startTime;
            juce::String sourceType = "original";
            juce::String sourceFile = clip.audioFile.getFullPathName();
            double playbackOffsetSec = clip.offset + clipTimeSec;
            bool renderedSegmentActive = false;
            bool correctedSourceActive = false;

            auto segmentIt = renderedPreviewSegmentSnapshot.find (clip.clipId);
            if (segmentIt != renderedPreviewSegmentSnapshot.end())
            {
                for (const auto& segment : segmentIt->second)
                {
                    if (clipTimeSec >= segment.startSec && clipTimeSec < segment.endSec)
                    {
                        renderedSegmentActive = true;
                        sourceType = "rendered_segment";
                        sourceFile = segment.audioFile.getFullPathName();
                        playbackOffsetSec = segment.fileOffsetSec + (clipTimeSec - segment.startSec);
                        break;
                    }
                }
            }

            if (! renderedSegmentActive
                && clip.originalAudioFile.existsAsFile()
                && clip.audioFile.existsAsFile()
                && clip.audioFile != clip.originalAudioFile)
            {
                correctedSourceActive = true;
                sourceType = "corrected_source";
            }

            auto* routeObj = new juce::DynamicObject();
            routeObj->setProperty ("trackId", trackId);
            routeObj->setProperty ("clipId", clip.clipId);
            routeObj->setProperty ("sourceType", sourceType);
            routeObj->setProperty ("audioFile", sourceFile);
            routeObj->setProperty ("clipTimeSec", clipTimeSec);
            routeObj->setProperty ("playbackOffsetSec", playbackOffsetSec);
            routeObj->setProperty ("renderedSegmentActive", renderedSegmentActive);
            routeObj->setProperty ("correctedSourceActive", correctedSourceActive);
            routeObj->setProperty ("clipVolumeDb", clip.volumeDB);
            routeObj->setProperty ("clipFadeInSec", clip.fadeIn);
            routeObj->setProperty ("clipFadeOutSec", clip.fadeOut);
            routes.add (juce::var (routeObj));
        }

        return juce::var (routes);
    };

    if (reusableMasterBuffer.getNumChannels() < 2 || reusableMasterBuffer.getNumSamples() < blockSize)
        reusableMasterBuffer.setSize(2, blockSize, false, false, true);
    if (reusableMasterBufferDouble.getNumChannels() < 2 || reusableMasterBufferDouble.getNumSamples() < blockSize)
        reusableMasterBufferDouble.setSize(2, blockSize, false, false, true);

    for (int pass = 0; pass < numPasses; ++pass)
    {
        logToDisk("renderProject: Pass " + juce::String(pass + 1) + " of " + juce::String(numPasses));

        // Reset all FX plugins at the start of each pass so they begin from a clean state.
        // This is critical for 2-pass normalization: pass 2 must produce identical output
        // to pass 1, which requires identical initial plugin state.
        for (auto& backup : pluginBackups)
        {
            if (backup.processor)
            {
                // NAM Rack owns file-backed models/IRs. Re-loading that state at
                // each normalization pass can start asynchronous convolution
                // work and used to arm a model transition. Its reset() now
                // clears all streaming/effect history without changing state.
                if (auto* rack = dynamic_cast<S13NAMRack*>(backup.processor))
                {
                    const bool restored = rack->restoreRenderPassStateInformation(
                        backup.savedState.getData(), static_cast<int>(backup.savedState.getSize()));
                    if (! restored)
                        logToDisk("renderProject: NAM render-pass scalar restore failed");
                    // Demo audition is a UI monitoring source, never project
                    // content. The saved live value is restored after export.
                    rack->auditionSource.store(0.0f, std::memory_order_relaxed);
                }
                else
                {
                    backup.processor->setStateInformation(backup.savedState.getData(),
                                                           (int)backup.savedState.getSize());
                }
                backup.processor->reset();
            }
        }
        for (auto* track : renderPreparedTracks)
            if (track != nullptr)
                track->resetOfflineRenderState();

        // Create fresh offline playback engine for each pass (deterministic reads)
        PlaybackEngine passPlayback;
        // The Lagrange render SRC path is stateful across blocks and currently
        // unsafe for arbitrary render offsets/ranges.  Keep exports on the
        // exact-position stateless interpolation path unless explicitly opted in.
        passPlayback.setRenderMode(useRenderLagrangeSrc);
        for (const auto& entry : renderedPreviewSegmentSnapshot)
        {
            for (const auto& segment : entry.second)
            {
                passPlayback.setClipRenderedPreviewSegment(entry.first,
                                                           segment.audioFile,
                                                           segment.startSec,
                                                           segment.endSec,
                                                           segment.fileOffsetSec);
            }
        }
        for (const auto& clip : clipSnapshot)
        {
            passPlayback.addClip(clip.audioFile, clip.startTime, clip.duration,
                                 clip.trackId, clip.offset, clip.volumeDB,
                                 clip.fadeIn, clip.fadeOut, clip.clipId,
                                 clip.originalAudioFile, clip.originalOffset);
        }

        // Create fresh metronome for each pass
        Metronome renderMet;
        if (renderMetronomeAudio)
        {
            renderMet.prepareToPlay(actualSampleRate, blockSize);
            renderMet.setBpm(tempo);
            renderMet.setTimeSignature(timeSigNumerator, timeSigDenominator);
            renderMet.setVolume(metronome.getVolume());
            renderMet.setAccentBeats(metronome.getAccentBeats());
            renderMet.setEnabled(true);
        }

        if (rtTracks)
        {
            for (const auto& entry : *rtTracks)
            {
                if (entry.sendAccumBuffer != nullptr)
                {
                    if (entry.sendAccumBuffer->getNumChannels() < 2 || entry.sendAccumBuffer->getNumSamples() < blockSize)
                        entry.sendAccumBuffer->setSize(2, blockSize, false, false, true);
                    entry.sendAccumBuffer->clear();
                }
                if (entry.sidechainOutputBuffer != nullptr)
                {
                    if (entry.sidechainOutputBuffer->getNumChannels() < 2 || entry.sidechainOutputBuffer->getNumSamples() < blockSize)
                        entry.sidechainOutputBuffer->setSize(2, blockSize, false, false, true);
                    entry.sidechainOutputBuffer->clear();
                }
            }
        }

        if (pass == 1)
        {
            // Second pass: calculate normalization gain
            if (peakLevel > 0.0f)
                normGain = 1.0f / peakLevel;
            else
                normGain = 1.0f;
            logToDisk("renderProject: Normalize gain = " + juce::String(normGain) +
                      " (peak was " + juce::String(peakLevel) + ")");
        }

        juce::int64 samplesRemaining = processingTotalSamples;
        double currentTimeSeconds = startTime;
        const double alignedTrackLatencySeconds = static_cast<double>(alignedTrackLatencySamples) / actualSampleRate;
        double samplePositionForMetronome = startTime * actualSampleRate - alignedTrackLatencySamples;
        float passPeak = 0.0f; // Track peak for this pass
        juce::int64 alignedSamplesVisited = 0;

        while (samplesRemaining > 0)
        {
            int samplesThisBlock = (int)std::min((juce::int64)blockSize, samplesRemaining);
            const juce::int64 renderBlockStartSample = processingTotalSamples - samplesRemaining;
            const auto outputWindow = getOfflineRenderBlockWindow(offlineRenderPlan,
                                                                   renderBlockStartSample,
                                                                   samplesThisBlock);
            const int admittedSourceSamples = static_cast<int>(juce::jlimit<juce::int64>(
                0,
                samplesThisBlock,
                sourceSamples - renderBlockStartSample));
            const bool sourceBoundaryBlock = admittedSourceSamples < samplesThisBlock
                && renderBlockStartSample <= sourceSamples;
            const double automationTimeSeconds = admittedSourceSamples > 0
                ? currentTimeSeconds
                : endTime;

            // Master buffer (always stereo internally)
            juce::AudioBuffer<float> masterBuffer(2, samplesThisBlock);
            masterBuffer.clear();
            const bool renderHybrid64 = processingPrecisionMode == ProcessingPrecisionMode::Hybrid64;
            const bool captureRenderChainBlock = renderChainDebugEnabled && pass == (numPasses - 1);

            if (renderHybrid64)
                reusableMasterBufferDouble.clear();

            if (captureRenderChainBlock)
            {
                chainPlaybackBlock.setSize (2, samplesThisBlock, false, false, true);
                chainTrackPostBlock.setSize (2, samplesThisBlock, false, false, true);
                chainMasterPreBlock.setSize (2, samplesThisBlock, false, false, true);
                chainMasterPostBlock.setSize (2, samplesThisBlock, false, false, true);
                chainWriterInputBlock.setSize (2, samplesThisBlock, false, false, true);
                chainPlaybackBlock.clear();
                chainTrackPostBlock.clear();
                chainMasterPreBlock.clear();
                chainMasterPostBlock.clear();
                chainWriterInputBlock.clear();
            }
            juce::Array<juce::var> chainBlockRoutes;

            // Add metronome if enabled
            if (renderMetronomeAudio)
            {
                renderMet.getNextAudioBlock(masterBuffer, samplePositionForMetronome);
                if (admittedSourceSamples < samplesThisBlock)
                    masterBuffer.clear(admittedSourceSamples,
                                       samplesThisBlock - admittedSourceSamples);
                if (renderHybrid64)
                    copyFloatBufferToDoubleBuffer(masterBuffer, reusableMasterBufferDouble, 2, samplesThisBlock);
            }

            if (rtTracks)
            {
                for (const auto& entry : *rtTracks)
                {
                    if (entry.sendAccumBuffer != nullptr)
                        entry.sendAccumBuffer->clear();
                    if (entry.sidechainOutputBuffer != nullptr)
                        entry.sidechainOutputBuffer->clear();
                }
            }

            if (useSimpleNoFxRenderLoop)
            {
                for (const auto& snap : trackSnapshots)
                {
                    if (isStemRender && snap.id != stemTrackId)
                        continue;
                    if (!isStemRender && snap.muted)
                        continue;
                    if (!isStemRender && anySoloed && !snap.soloed)
                        continue;

                    juce::AudioBuffer<float> trackBuffer(2, samplesThisBlock);
                    trackBuffer.clear();
                    passPlayback.fillTrackBuffer(snap.id, trackBuffer, currentTimeSeconds,
                                                 samplesThisBlock, actualSampleRate);
                    if (admittedSourceSamples < samplesThisBlock)
                        trackBuffer.clear(admittedSourceSamples,
                                          samplesThisBlock - admittedSourceSamples);

                    if (captureRenderChainBlock)
                    {
                        addToSignalChainCapture(chainPlaybackBlock, 0, trackBuffer, samplesThisBlock);
                        auto routeTrace = buildRenderChainRouteTrace(snap.id,
                                                                     currentTimeSeconds,
                                                                     admittedSourceSamples);
                        if (auto* routeArray = routeTrace.getArray())
                        {
                            for (const auto& route : *routeArray)
                                chainBlockRoutes.add(route);
                        }
                    }

                    const float volumeGain = juce::Decibels::decibelsToGain(snap.volumeDB);
                    float leftGain = 1.0f;
                    float rightGain = 1.0f;
                    computePanLawGains(currentPanLaw, snap.pan, volumeGain, leftGain, rightGain);
                    juce::FloatVectorOperations::multiply(trackBuffer.getWritePointer(0), leftGain, samplesThisBlock);
                    juce::FloatVectorOperations::multiply(trackBuffer.getWritePointer(1), rightGain, samplesThisBlock);

                    if (captureRenderChainBlock)
                        addToSignalChainCapture(chainTrackPostBlock, 0, trackBuffer, samplesThisBlock);

                    for (int ch = 0; ch < 2; ++ch)
                    {
                        if (renderHybrid64)
                        {
                            auto* dest = reusableMasterBufferDouble.getWritePointer(ch);
                            auto* src = trackBuffer.getReadPointer(ch);
                            for (int sample = 0; sample < samplesThisBlock; ++sample)
                                dest[sample] += static_cast<double>(src[sample]);
                        }
                        else
                        {
                            masterBuffer.addFrom(ch, 0, trackBuffer, ch, 0, samplesThisBlock);
                        }
                    }
                }
            }
            else if (rtTracks && !rtTracks->empty())
            {
                constexpr int kMaxOfflineTracks = 64;
                int processedOrder[kMaxOfflineTracks];
                int orderCount = 0;
                buildSidechainProcessingOrder(*rtTracks, processedOrder, orderCount, kMaxOfflineTracks);

                for (int orderIdx = 0; orderIdx < orderCount; ++orderIdx)
                {
                    const auto& trackEntry = (*rtTracks)[static_cast<size_t>(processedOrder[orderIdx])];
                    auto* track = dynamic_cast<TrackProcessor*>(trackEntry.node != nullptr ? trackEntry.node->getProcessor() : nullptr);
                    if (track == nullptr)
                        continue;

                    if (isStemRender && trackEntry.id != stemTrackId)
                        continue;

                    auto snapshotIt = trackSnapshotById.find(trackEntry.id);
                    if (!isStemRender)
                    {
                        if (snapshotIt == trackSnapshotById.end())
                            continue;
                        if (snapshotIt->second.muted)
                            continue;
                        if (anySoloed && !snapshotIt->second.soloed)
                            continue;
                    }

                    juce::AudioBuffer<float> trackBuffer(2, samplesThisBlock);
                    trackBuffer.clear();

                    if (!isStemRender && trackEntry.sendAccumBuffer != nullptr && trackEntry.sendAccumBuffer->getNumSamples() >= samplesThisBlock)
                    {
                        auto& accumBuffer = *trackEntry.sendAccumBuffer;
                        for (int ch = 0; ch < juce::jmin(2, accumBuffer.getNumChannels()); ++ch)
                            juce::FloatVectorOperations::add(trackBuffer.getWritePointer(ch),
                                                             accumBuffer.getReadPointer(ch),
                                                             samplesThisBlock);
                        accumBuffer.clear();
                    }

                    if (!track->hasActiveARA())
                    {
                        juce::AudioBuffer<float> playbackBuffer(2, samplesThisBlock);
                        playbackBuffer.clear();
                        passPlayback.fillTrackBuffer(trackEntry.id, playbackBuffer, currentTimeSeconds,
                                                     samplesThisBlock, actualSampleRate);
                        if (admittedSourceSamples < samplesThisBlock)
                            playbackBuffer.clear(admittedSourceSamples,
                                                 samplesThisBlock - admittedSourceSamples);
                        for (int channel = 0; channel < 2; ++channel)
                            trackBuffer.addFrom(channel,
                                                0,
                                                playbackBuffer,
                                                channel,
                                                0,
                                                samplesThisBlock);
                    }
                    if (captureRenderChainBlock)
                    {
                        addToSignalChainCapture (chainPlaybackBlock, 0, trackBuffer, samplesThisBlock);
                        auto routeTrace = buildRenderChainRouteTrace (trackEntry.id,
                                                                      currentTimeSeconds,
                                                                      admittedSourceSamples);
                        if (auto* routeArray = routeTrace.getArray())
                        {
                            for (const auto& route : *routeArray)
                                chainBlockRoutes.add (route);
                        }
                    }

                    if (!isStemRender && !trackEntry.sidechainSourceIds.empty())
                    {
                        const juce::AudioBuffer<float>* sidechainBuffer = nullptr;
                        for (const auto& sourceId : trackEntry.sidechainSourceIds)
                        {
                            if (sourceId.isEmpty())
                                continue;

                            for (const auto& candidate : *rtTracks)
                            {
                                if (candidate.id == sourceId && candidate.sidechainOutputBuffer != nullptr)
                                {
                                    sidechainBuffer = candidate.sidechainOutputBuffer.get();
                                    break;
                                }
                            }

                            if (sidechainBuffer != nullptr)
                                break;
                        }

                        track->setSidechainBuffer(sidechainBuffer);
                    }
                    else
                    {
                        track->setSidechainBuffer(nullptr);
                    }

                    track->setCurrentBlockPosition(automationTimeSeconds);
                    if (auto* instrument = track->getInstrument())
                        instrument->setPlayHead(this);
                    juce::MidiBuffer midiMessages;
                    if (admittedSourceSamples > 0)
                        midiMessages = buildTrackMidiBlock(trackEntry.id,
                                                           currentTimeSeconds,
                                                           admittedSourceSamples,
                                                           actualSampleRate,
                                                           true);
                    if (sourceBoundaryBlock)
                    {
                        const int noteOffSample = juce::jlimit(0,
                                                               samplesThisBlock - 1,
                                                               admittedSourceSamples);
                        for (int channel = 1; channel <= 16; ++channel)
                        {
                            midiMessages.addEvent(juce::MidiMessage::controllerEvent(channel, 64, 0), noteOffSample);
                            midiMessages.addEvent(juce::MidiMessage::allNotesOff(channel), noteOffSample);
                        }
                    }
                    if (!track->tryProcessBlock(trackBuffer, midiMessages))
                        continue;
                    if (captureRenderChainBlock)
                        addToSignalChainCapture (chainTrackPostBlock, 0, trackBuffer, samplesThisBlock);

                    if (!isStemRender && trackEntry.sidechainOutputBuffer != nullptr)
                    {
                        auto& sidechainOut = *trackEntry.sidechainOutputBuffer;
                        if (sidechainOut.getNumChannels() < 2 || sidechainOut.getNumSamples() < samplesThisBlock)
                            sidechainOut.setSize(2, samplesThisBlock, false, false, true);
                        for (int ch = 0; ch < juce::jmin(2, trackBuffer.getNumChannels()); ++ch)
                            sidechainOut.copyFrom(ch, 0, trackBuffer, ch, 0, samplesThisBlock);
                    }

                    if (!isStemRender && !trackEntry.sends.empty())
                    {
                        const auto& preFaderBuffer = track->getPreFaderBuffer();
                        for (const auto& send : trackEntry.sends)
                        {
                            if (!send.enabled || send.level <= 0.0f || send.destTrackId.isEmpty())
                                continue;

                            for (const auto& destEntry : *rtTracks)
                            {
                                if (destEntry.id != send.destTrackId || destEntry.sendAccumBuffer == nullptr)
                                    continue;

                                auto& destBuffer = *destEntry.sendAccumBuffer;
                                if (destBuffer.getNumChannels() < 2 || destBuffer.getNumSamples() < samplesThisBlock)
                                    destBuffer.setSize(2, samplesThisBlock, false, false, true);

                                const auto& sourceBuffer = send.preFader ? preFaderBuffer : trackBuffer;
                                const int sourceChannels = sourceBuffer.getNumChannels();
                                const int destChannels = destBuffer.getNumChannels();
                                const float phaseMultiplier = send.phaseInvert ? -1.0f : 1.0f;
                                const float panAngle = (send.pan + 1.0f) * juce::MathConstants<float>::pi / 4.0f;
                                const float leftGain = std::cos(panAngle) * send.level * phaseMultiplier;
                                const float rightGain = std::sin(panAngle) * send.level * phaseMultiplier;

                                if (destChannels >= 2 && sourceChannels >= 2)
                                {
                                    for (int sample = 0; sample < samplesThisBlock; ++sample)
                                    {
                                        destBuffer.getWritePointer(0)[sample] += sourceBuffer.getReadPointer(0)[sample] * leftGain;
                                        destBuffer.getWritePointer(1)[sample] += sourceBuffer.getReadPointer(1)[sample] * rightGain;
                                    }
                                }
                                else if (destChannels >= 1 && sourceChannels >= 1)
                                {
                                    for (int sample = 0; sample < samplesThisBlock; ++sample)
                                        destBuffer.getWritePointer(0)[sample] += sourceBuffer.getReadPointer(0)[sample] * send.level;
                                }

                                break;
                            }
                        }
                    }

                    if (!track->getMasterSendEnabled())
                        continue;

                    for (int ch = 0; ch < juce::jmin(2, trackBuffer.getNumChannels()); ++ch)
                    {
                        if (renderHybrid64)
                        {
                            auto* dest = reusableMasterBufferDouble.getWritePointer(ch);
                            auto* src = trackBuffer.getReadPointer(ch);
                            for (int sample = 0; sample < samplesThisBlock; ++sample)
                                dest[sample] += static_cast<double>(src[sample]);
                        }
                        else
                        {
                            masterBuffer.addFrom(ch, 0, trackBuffer, ch, 0, samplesThisBlock);
                        }
                    }
                }
            }

            if (captureRenderChainBlock)
            {
                if (renderHybrid64)
                    copyDoubleBufferToFloatBuffer (reusableMasterBufferDouble, masterBuffer, 2, samplesThisBlock);

                const int chainCaptureOffset = static_cast<int> (std::min<juce::int64> (
                    renderBlockStartSample,
                    static_cast<juce::int64> (std::numeric_limits<int>::max())));
                addToSignalChainCapture (chainPlaybackTap, chainCaptureOffset, chainPlaybackBlock, samplesThisBlock);
                addToSignalChainCapture (chainTrackPostTap, chainCaptureOffset, chainTrackPostBlock, samplesThisBlock);
                chainMasterPreBlock.copyFrom (0, 0, masterBuffer, 0, 0, samplesThisBlock);
                chainMasterPreBlock.copyFrom (1, 0, masterBuffer, 1, 0, samplesThisBlock);
                copyToSignalChainCapture (chainMasterPreTap, chainCaptureOffset, masterBuffer, samplesThisBlock);
            }

            if (!isStemRender && renderMasterStage && !renderMasterStage->slots.empty())
            {
                float* masterChannelData[2] { masterBuffer.getWritePointer(0), masterBuffer.getWritePointer(1) };
                processMasterFXChain(std::static_pointer_cast<const ActiveFXStage>(renderMasterStage),
                                     masterChannelData, 2, samplesThisBlock, renderHybrid64);
            }

            if (captureRenderChainBlock)
            {
                if (renderHybrid64)
                    copyDoubleBufferToFloatBuffer (reusableMasterBufferDouble, masterBuffer, 2, samplesThisBlock);

                const int chainCaptureOffset = static_cast<int> (std::min<juce::int64> (
                    renderBlockStartSample,
                    static_cast<juce::int64> (std::numeric_limits<int>::max())));
                chainMasterPostBlock.copyFrom (0, 0, masterBuffer, 0, 0, samplesThisBlock);
                chainMasterPostBlock.copyFrom (1, 0, masterBuffer, 1, 0, samplesThisBlock);
                copyToSignalChainCapture (chainMasterPostTap, chainCaptureOffset, masterBuffer, samplesThisBlock);
            }

            if (!isStemRender)
            {
                float* masterChannelData[2] { masterBuffer.getWritePointer(0), masterBuffer.getWritePointer(1) };
                applyMasterGainPanMono(masterChannelData, 2, samplesThisBlock,
                                       juce::jmin(currentTimeSeconds - alignedTrackLatencySeconds,
                                                  endTime),
                                       renderHybrid64);
            }

            // Apply normalization gain (pass 2 only)
            if (pass == 1 && normGain != 1.0f)
            {
                if (renderHybrid64)
                {
                    applyGainToDoubleBuffer(reusableMasterBufferDouble, 2, samplesThisBlock, normGain);
                }
                else
                {
                    for (int ch = 0; ch < 2; ++ch)
                        juce::FloatVectorOperations::multiply(masterBuffer.getWritePointer(ch), normGain, samplesThisBlock);
                }
            }

            // Measure only the aligned output window. Startup latency is rendered
            // to warm/flush the chain, but must not influence normalization.
            if (outputWindow.numSamples > 0)
            {
                if (renderHybrid64)
                {
                    passPeak = juce::jmax(passPeak,
                                          findPeakInDoubleBufferRange(reusableMasterBufferDouble,
                                                                      2,
                                                                      outputWindow.sourceOffset,
                                                                      outputWindow.numSamples));
                }
                else
                {
                    for (int ch = 0; ch < 2; ++ch)
                    {
                        auto range = masterBuffer.findMinMax(ch,
                                                             outputWindow.sourceOffset,
                                                             outputWindow.numSamples);
                        float chPeak = std::max(std::abs(range.getStart()), std::abs(range.getEnd()));
                        if (chPeak > passPeak) passPeak = chPeak;
                    }
                }
            }

            if (pass == 0 && normalize)
            {
                // Pass 1: accumulate peak for normalization
                if (passPeak > peakLevel) peakLevel = passPeak;
            }

            // Write to file (final pass only)
            bool isFinalPass = (pass == numPasses - 1);
            if (isFinalPass && outputWindow.numSamples > 0)
            {
                if (renderHybrid64)
                    copyDoubleBufferToFloatBuffer(reusableMasterBufferDouble, masterBuffer, 2, samplesThisBlock);

                // Apply dither if requested (before bit-depth truncation by the writer)
                if (ditherMode > 0 && bitDepth < 32)
                {
                    // ditherMode 1 = TPDF, 2 = noise-shaped (first-order high-pass)
                    float ditherAmp = 1.0f / static_cast<float>(1 << (bitDepth - 1)); // 1 LSB
                    for (int ch = 0; ch < masterBuffer.getNumChannels(); ++ch)
                    {
                        float* data = masterBuffer.getWritePointer(ch);
                        const int outputEnd = outputWindow.sourceOffset + outputWindow.numSamples;
                        for (int s = outputWindow.sourceOffset; s < outputEnd; ++s)
                        {
                            // TPDF: two uniform randoms → triangular PDF
                            float r1 = (ditherRng.nextFloat() * 2.0f - 1.0f) * ditherAmp;
                            float r2 = (ditherRng.nextFloat() * 2.0f - 1.0f) * ditherAmp;
                            float noise = r1 + r2;

                            if (ditherMode == 2)
                            {
                                // First-order noise shaping: subtract previous quantization error
                                float shaped = noise - ditherErrorState[ch];
                                float original = data[s];
                                data[s] = original + shaped;
                                // Quantize to calculate error for next sample
                                float scale = static_cast<float>(1 << (bitDepth - 1));
                                float quantized = std::round(data[s] * scale) / scale;
                                ditherErrorState[ch] = quantized - original;
                            }
                            else
                            {
                                data[s] += noise;
                            }
                        }
                    }
                }

                if (captureRenderChainBlock)
                {
                    const int chainCaptureOffset = static_cast<int> (std::min<juce::int64> (
                        outputWindow.outputStartSample,
                        static_cast<juce::int64> (std::numeric_limits<int>::max())));
                    for (int ch = 0; ch < 2; ++ch)
                    {
                        chainWriterInputBlock.copyFrom(ch, 0, masterBuffer, ch,
                                                       outputWindow.sourceOffset,
                                                       outputWindow.numSamples);
                        if (chainCaptureOffset < chainWriterInputTap.getNumSamples())
                        {
                            const int samplesToCapture = juce::jmin(outputWindow.numSamples,
                                chainWriterInputTap.getNumSamples() - chainCaptureOffset);
                            if (samplesToCapture > 0)
                                chainWriterInputTap.copyFrom(ch, chainCaptureOffset, masterBuffer, ch,
                                                             outputWindow.sourceOffset, samplesToCapture);
                        }
                    }

                    auto* blockObj = new juce::DynamicObject();
                    blockObj->setProperty ("pass", pass + 1);
                    blockObj->setProperty ("blockStartSec", currentTimeSeconds);
                    blockObj->setProperty ("blockStartSample", static_cast<int64> (renderBlockStartSample));
                    blockObj->setProperty ("numSamples", samplesThisBlock);
                    blockObj->setProperty ("writerSourceOffset", outputWindow.sourceOffset);
                    blockObj->setProperty ("writerNumSamples", outputWindow.numSamples);
                    blockObj->setProperty ("writerOutputStartSample", static_cast<int64> (outputWindow.outputStartSample));
                    blockObj->setProperty ("playback", makeSignalChainBufferStats (chainPlaybackBlock, samplesThisBlock));
                    blockObj->setProperty ("trackPost", makeSignalChainBufferStats (chainTrackPostBlock, samplesThisBlock));
                    blockObj->setProperty ("masterPreFx", makeSignalChainBufferStats (chainMasterPreBlock, samplesThisBlock));
                    blockObj->setProperty ("masterPostFx", makeSignalChainBufferStats (chainMasterPostBlock, samplesThisBlock));
                    blockObj->setProperty ("writerInput", makeSignalChainBufferStats (chainWriterInputBlock,
                                                                                       outputWindow.numSamples));
                    blockObj->setProperty ("routes", juce::var (chainBlockRoutes));
                    renderChainBlockReports.add (juce::var (blockObj));
                }

                if (numChannels == 1)
                {
                    // Mono downmix: average L+R
                    juce::AudioBuffer<float> monoBuffer(1, outputWindow.numSamples);
                    monoBuffer.clear();
                    monoBuffer.addFrom(0, 0, masterBuffer, 0, outputWindow.sourceOffset,
                                       outputWindow.numSamples, 0.5f);
                    monoBuffer.addFrom(0, 0, masterBuffer, 1, outputWindow.sourceOffset,
                                       outputWindow.numSamples, 0.5f);
                    writer->writeFromAudioSampleBuffer(monoBuffer, 0, outputWindow.numSamples);
                }
                else
                {
                    writer->writeFromAudioSampleBuffer(masterBuffer,
                                                       outputWindow.sourceOffset,
                                                       outputWindow.numSamples);
                }
            }

            alignedSamplesVisited += outputWindow.numSamples;

            currentTimeSeconds += (double)samplesThisBlock / actualSampleRate;
            samplePositionForMetronome += samplesThisBlock;
            samplesRemaining -= samplesThisBlock;
        }

        if (alignedSamplesVisited != totalSamples)
        {
            logToDisk("renderProject: FAIL - aligned writer window visited "
                      + juce::String(alignedSamplesVisited) + " of " + juce::String(totalSamples)
                      + " output samples");
            writer.reset();
            restorePreparedTracksForRealtime();
            isRendering = false;
            return false;
        }

        logToDisk("renderProject: Pass " + juce::String(pass + 1)
                  + " complete. Peak level: " + juce::String(passPeak)
                  + " alignedSamples=" + juce::String(alignedSamplesVisited));
    }

    // Flush and close
    writer.reset();

    if (renderChainDebugEnabled)
    {
        auto* reportObj = new juce::DynamicObject();
        reportObj->setProperty ("schemaVersion", 1);
        reportObj->setProperty ("purpose", "signal_chain_first_render_debug");
        reportObj->setProperty ("source", source);
        reportObj->setProperty ("renderFile", renderFile.getFullPathName());
        reportObj->setProperty ("requestedOutputFile", outputFile.getFullPathName());
        reportObj->setProperty ("format", format);
        reportObj->setProperty ("actualSampleRate", actualSampleRate);
        reportObj->setProperty ("bitDepth", bitDepth);
        reportObj->setProperty ("channels", numChannels);
        reportObj->setProperty ("normalize", normalize);
        reportObj->setProperty ("ditherMode", ditherMode);
        reportObj->setProperty ("startTimeSec", startTime);
        reportObj->setProperty ("endTimeSec", endTime);
        reportObj->setProperty ("totalSamples", static_cast<int64> (totalSamples));
        reportObj->setProperty ("processingSamples", static_cast<int64> (processingTotalSamples));
        reportObj->setProperty ("sourceSamples", static_cast<int64> (sourceSamples));
        reportObj->setProperty ("effectTailSamples", static_cast<int64> (offlineRenderPlan.effectTailSamples));
        reportObj->setProperty ("alignedTrackLatencySamples", alignedTrackLatencySamples);
        reportObj->setProperty ("masterLatencySamples", masterLatencySamples);
        reportObj->setProperty ("trimmedStartupLatencySamples", totalRenderLatencySamples);
        reportObj->setProperty ("effectiveEffectTailSec", offlineRenderPlan.effectiveTailSeconds);
        reportObj->setProperty ("capturedSamples", renderChainCaptureSamples);
        reportObj->setProperty ("captureTruncated", renderChainCaptureSamples < totalSamples);
        reportObj->setProperty ("pitchPreviewRoutesClearedBeforeSnapshot", true);
        reportObj->setProperty ("renderedPitchSegmentsDroppedBeforeSnapshot", staleRenderedPitchSegmentsDropped);
        reportObj->setProperty ("blockReports", juce::var (renderChainBlockReports));

        auto* chainObj = new juce::DynamicObject();
        chainObj->setProperty ("live", "clip route resolution -> PlaybackEngine read/mix -> TrackProcessor -> sends/sidechain -> master/monitoring FX -> gain/pan/mono -> meters/spectrum -> audio device");
        chainObj->setProperty ("render", "renderProject -> render PlaybackEngine snapshot -> TrackProcessor -> master FX/gain -> writer");
        reportObj->setProperty ("chainReference", juce::var (chainObj));

        auto* stageObj = new juce::DynamicObject();
        auto writeStage = [&] (const juce::String& name,
                               const juce::AudioBuffer<float>& buffer)
        {
            auto* obj = new juce::DynamicObject();
            const auto wav = renderChainDebugDir.getChildFile (name + ".wav");
            const bool wrote = renderChainCaptureSamples > 0
                && writeBufferToWavFile (buffer, renderChainCaptureSamples, actualSampleRate, wav);
            obj->setProperty ("filePath", wrote ? wav.getFullPathName() : juce::String());
            obj->setProperty ("wrote", wrote);
            obj->setProperty ("stats", makeSignalChainBufferStats (buffer, renderChainCaptureSamples));
            stageObj->setProperty (name, juce::var (obj));
        };

        writeStage ("playback_output", chainPlaybackTap);
        writeStage ("track_post_processing", chainTrackPostTap);
        writeStage ("master_pre_fx", chainMasterPreTap);
        writeStage ("master_post_fx", chainMasterPostTap);
        writeStage ("writer_input", chainWriterInputTap);

        juce::AudioBuffer<float> writerOutputBuffer;
        double writerOutputSampleRate = 0.0;
        auto* writerOutputObj = new juce::DynamicObject();
        writerOutputObj->setProperty ("filePath", renderFile.getFullPathName());
        if (readAudioFileForParity (renderFile, writerOutputBuffer, writerOutputSampleRate))
        {
            writerOutputObj->setProperty ("readable", true);
            writerOutputObj->setProperty ("sampleRate", writerOutputSampleRate);
            writerOutputObj->setProperty ("stats", makeSignalChainBufferStats (
                writerOutputBuffer,
                juce::jmin (writerOutputBuffer.getNumSamples(), renderChainCaptureSamples)));
        }
        else
        {
            writerOutputObj->setProperty ("readable", false);
        }
        stageObj->setProperty ("writer_output", juce::var (writerOutputObj));
        reportObj->setProperty ("stages", juce::var (stageObj));

        const auto reportFile = renderChainDebugDir.getChildFile ("render_chain_report.json");
        reportFile.replaceWithText (juce::JSON::toString (juce::var (reportObj), true));
        logToDisk ("renderProject: signal-chain debug report=" + reportFile.getFullPathName());
    }

    // ========== 9. FFmpeg post-processing (encoding or final SRC) ==========
    if (needsFFmpegPostProcess)
    {
        logToDisk("renderProject: Starting FFmpeg post-processing (encoding/final SRC)...");
        // Let FFmpeg perform the final output SRC/encode step.
        bool ffmpegOk = convertWithFFmpeg(renderFile, outputFile, formatLower,
                                          requestedOutputSampleRate, codecQuality,
                                          bitDepth, numChannels);

        // Clean up temp file
        renderFile.deleteFile();

        if (!ffmpegOk)
        {
            logToDisk("renderProject: FAIL - FFmpeg post-processing failed");
            restorePreparedTracksForRealtime();
            isRendering = false;
            return false;
        }
    }

    // ========== 10. Restore plugin state for real-time playback ==========
    // Re-prepare all FX plugins for the device's buffer size and restore their
    // saved state so real-time playback continues as if render never happened.
    // Clamp max-block to at least 512 (same rationale as track FX preparation).
    restorePreparedTracksForRealtime();
    logToDisk("renderProject: Restored " + juce::String((int)pluginBackups.size()) + " FX plugins for real-time");

    // Re-enable audio callback
    isRendering = false;

    logToDisk("renderProject: SUCCESS - " + outputFile.getFullPathName() +
              " (" + juce::String(outputFile.getSize() / 1024) + " KB)");

    return true;
}

juce::var AudioEngine::capturePitchAuditionPlayback(const juce::String& trackId,
                                                    const juce::String& clipId,
                                                    double startTime,
                                                    double duration,
                                                    const juce::String& filePath,
                                                    double sampleRate,
                                                    bool offlineRenderMode)
{
    auto* resultObj = new juce::DynamicObject();
    resultObj->setProperty("success", false);
    resultObj->setProperty("trackId", trackId);
    resultObj->setProperty("clipId", clipId);
    resultObj->setProperty("filePath", filePath);
    resultObj->setProperty("offlineRenderMode", offlineRenderMode);

    if (trackId.isEmpty() || filePath.isEmpty())
    {
        resultObj->setProperty("error", "missing trackId or output path");
        return juce::var(resultObj);
    }

    const double safeSampleRate = sampleRate > 0.0 ? sampleRate : 44100.0;
    const double safeStart = std::max(0.0, startTime);
    const double safeDuration = std::max(0.0, duration);
    if (safeDuration <= 0.0)
    {
        resultObj->setProperty("error", "duration must be positive");
        return juce::var(resultObj);
    }

    const int totalSamples = juce::jmax(1, static_cast<int>(std::ceil(safeDuration * safeSampleRate)));
    juce::AudioBuffer<float> capture(2, totalSamples);
    capture.clear();

    const bool wasRenderMode = isRendering.load();
    playbackEngine.setRenderMode(offlineRenderMode);

    int written = 0;
    const int blockSize = 1024;
    juce::AudioBuffer<float> block(2, blockSize);
    float peak = 0.0f;
    double energy = 0.0;
    juce::int64 energySamples = 0;
    juce::Array<juce::var> routeTrace;

    while (written < totalSamples)
    {
        const int samplesThisBlock = juce::jmin(blockSize, totalSamples - written);
        block.setSize(2, samplesThisBlock, false, false, true);
        block.clear();

        const double blockTime = safeStart + (static_cast<double>(written) / safeSampleRate);
        const auto sourceStatus = playbackEngine.getClipPlaybackSourceAtTime(trackId, clipId, blockTime);
        auto* routeObj = new juce::DynamicObject();
        routeObj->setProperty("blockStartSec", blockTime);
        routeObj->setProperty("blockDurationSec", static_cast<double>(samplesThisBlock) / safeSampleRate);
        routeObj->setProperty("clipFound", sourceStatus.clipFound);
        routeObj->setProperty("clipTimeSec", sourceStatus.clipTime);
        routeObj->setProperty("sourceType", sourceStatus.sourceType);
        routeObj->setProperty("audioFile", sourceStatus.audioFile);
        routeObj->setProperty("playbackOffsetSec", sourceStatus.playbackOffset);
        routeObj->setProperty("renderedSegmentActiveAtTime", sourceStatus.renderedSegmentActiveAtTime);
        routeObj->setProperty("correctedSourceActiveAtTime", sourceStatus.correctedSourceActiveAtTime);
        routeTrace.add(juce::var(routeObj));
        playbackEngine.fillTrackBuffer(trackId, block, blockTime, samplesThisBlock, safeSampleRate);

        for (int ch = 0; ch < 2; ++ch)
        {
            capture.copyFrom(ch, written, block, ch, 0, samplesThisBlock);
            const auto range = juce::FloatVectorOperations::findMinAndMax(block.getReadPointer(ch), samplesThisBlock);
            peak = juce::jmax(peak, juce::jmax(std::abs(range.getStart()), std::abs(range.getEnd())));
            const float* data = block.getReadPointer(ch);
            for (int i = 0; i < samplesThisBlock; ++i)
            {
                const double s = static_cast<double>(data[i]);
                energy += s * s;
                ++energySamples;
            }
        }

        written += samplesThisBlock;
    }

    playbackEngine.setRenderMode(wasRenderMode);

    const juce::File outputFile(filePath);
    outputFile.getParentDirectory().createDirectory();
    const bool wrote = writeBufferToWavFile(capture, totalSamples, safeSampleRate, outputFile);
    if (!wrote)
    {
        resultObj->setProperty("error", "failed to write audition capture wav");
        return juce::var(resultObj);
    }

    resultObj->setProperty("success", true);
    resultObj->setProperty("filePath", outputFile.getFullPathName());
    resultObj->setProperty("startSec", safeStart);
    resultObj->setProperty("durationSec", static_cast<double>(totalSamples) / safeSampleRate);
    resultObj->setProperty("sampleRate", safeSampleRate);
    resultObj->setProperty("peak", peak);
    resultObj->setProperty("rms", energySamples > 0 ? std::sqrt(energy / static_cast<double>(energySamples)) : 0.0);
    resultObj->setProperty("source", offlineRenderMode ? "offline_render_engine" : "live_playback_engine");
    resultObj->setProperty("routeTrace", juce::var(routeTrace));
    return juce::var(resultObj);
}

juce::var AudioEngine::capturePitchBakedContext(const juce::String& sourceFile,
                                                double startSec,
                                                double durationSec,
                                                const juce::String& filePath)
{
    return writePitchBakedContextWav(juce::File(sourceFile),
                                     startSec,
                                     durationSec,
                                     juce::File(filePath));
}

juce::var AudioEngine::comparePitchDebugAudioFiles(const juce::String& referenceFile,
                                                   const juce::String& candidateFile,
                                                   double captureStartClipSec,
                                                   double noteStartClipSec,
                                                   double noteEndClipSec)
{
    return comparePitchParityFiles(juce::File(referenceFile),
                                   juce::File(candidateFile),
                                   captureStartClipSec,
                                   noteStartClipSec,
                                   noteEndClipSec);
}

bool AudioEngine::renderProjectWithDither(const juce::String& source, double startTime, double endTime,
                                          const juce::String& filePath, const juce::String& format,
                                          double renderSampleRate, int bitDepth, int numChannels,
                                          bool normalize, bool addTail, double tailLengthMs,
                                          const juce::String& ditherType,
                                          bool includeMetronome)
{
    // Map dither type string to mode: "tpdf" → 1, "shaped" → 2, else → 0
    if (ditherType == "tpdf")
        pendingDitherMode_ = 1;
    else if (ditherType == "shaped")
        pendingDitherMode_ = 2;
    else
        pendingDitherMode_ = 0;

    return renderProject(source, startTime, endTime, filePath, format,
                         renderSampleRate, bitDepth, numChannels,
                         normalize, addTail, tailLengthMs, includeMetronome);
}

//==============================================================================
// Automation

static AutomationMode parseAutomationMode(const juce::String& modeStr)
{
    if (modeStr == "read")  return AutomationMode::Read;
    if (modeStr == "write") return AutomationMode::Write;
    if (modeStr == "touch") return AutomationMode::Touch;
    if (modeStr == "latch") return AutomationMode::Latch;
    return AutomationMode::Off;
}

static juce::String automationModeToString(AutomationMode mode)
{
    switch (mode)
    {
        case AutomationMode::Read:  return "read";
        case AutomationMode::Write: return "write";
        case AutomationMode::Touch: return "touch";
        case AutomationMode::Latch: return "latch";
        case AutomationMode::Off:
        default:                    return "off";
    }
}

void AudioEngine::setAutomationPoints(const juce::String& trackId, const juce::String& parameterId,
                                       const juce::String& pointsJSON)
{
    AutomationList* list = nullptr;
    if (trackId == "master")
    {
        if (parameterId == "volume") list = &masterVolumeAutomation;
        else if (parameterId == "pan") list = &masterPanAutomation;
        if (!list)
            return;
    }
    else
    {
        auto it = trackMap.find(trackId);
        if (it == trackMap.end() || !it->second)
            return;
        auto target = it->second->resolveAutomationTarget(parameterId, true);
        if (!target.has_value() || target->list == nullptr)
            return;
        list = target->list;
    }

    auto parsed = juce::JSON::parse(pointsJSON);
    if (!parsed.isArray())
        return;

    auto* arr = parsed.getArray();
    std::vector<AutomationPoint> points;
    points.reserve(static_cast<size_t>(arr->size()));

    for (const auto& item : *arr)
    {
        double timeSec = item.getProperty("time", 0.0);
        float value = static_cast<float>(static_cast<double>(item.getProperty("value", 0.0)));
        points.push_back({ timeSec, value });
    }

    list->setPoints(std::move(points));

    juce::Logger::writeToLog("AudioEngine: Set " + juce::String(static_cast<int>(points.size())) +
                             " automation points for track " + trackId + " param " + parameterId);
}

void AudioEngine::replaceAutomationPointsInRange(const juce::String& trackId, const juce::String& parameterId,
                                                 double startTimeSeconds, double endTimeSeconds,
                                                 const juce::String& pointsJSON)
{
    AutomationList* list = nullptr;
    if (trackId == "master")
    {
        if (parameterId == "volume") list = &masterVolumeAutomation;
        else if (parameterId == "pan") list = &masterPanAutomation;
        if (!list)
            return;
    }
    else
    {
        auto it = trackMap.find(trackId);
        if (it == trackMap.end() || !it->second)
            return;
        auto target = it->second->resolveAutomationTarget(parameterId, true);
        if (!target.has_value() || target->list == nullptr)
            return;
        list = target->list;
    }

    auto parsed = juce::JSON::parse(pointsJSON);
    if (!parsed.isArray())
        return;

    auto* arr = parsed.getArray();
    std::vector<AutomationPoint> points;
    points.reserve(static_cast<size_t>(arr->size()));
    for (const auto& item : *arr)
    {
        const double timeSec = item.getProperty("time", 0.0);
        const float value = static_cast<float>(static_cast<double>(item.getProperty("value", 0.0)));
        points.push_back({ timeSec, value });
    }

    list->replacePointsInRange(startTimeSeconds, endTimeSeconds, std::move(points));
}

void AudioEngine::setAutomationMode(const juce::String& trackId, const juce::String& parameterId,
                                     const juce::String& modeStr)
{
    AutomationList* list = nullptr;
    float defaultValue = 0.0f;
    if (trackId == "master")
    {
        if (parameterId == "volume") list = &masterVolumeAutomation;
        else if (parameterId == "pan") list = &masterPanAutomation;
        if (!list)
            return;

        auto mode = parseAutomationMode(modeStr);
        list->setMode(mode);

        if (mode != AutomationMode::Off)
        {
            if (parameterId == "volume")
                defaultValue = masterVolume;
            else if (parameterId == "pan")
                defaultValue = masterPan;
            list->setDefaultValue(defaultValue);
        }
    }
    else
    {
        auto it = trackMap.find(trackId);
        if (it == trackMap.end() || !it->second)
            return;

        auto target = it->second->resolveAutomationTarget(parameterId, true);
        if (!target.has_value() || target->list == nullptr)
            return;
        list = target->list;

        auto mode = parseAutomationMode(modeStr);
        list->setMode(mode);

        if (mode != AutomationMode::Off)
            list->setDefaultValue(it->second->getAutomationDefaultValue(*target));
    }

    juce::Logger::writeToLog("AudioEngine: Set automation mode for track " + trackId +
                             " param " + parameterId + " = " + modeStr);
}

juce::String AudioEngine::getAutomationMode(const juce::String& trackId, const juce::String& parameterId)
{
    AutomationList* list = nullptr;
    if (trackId == "master")
    {
        if (parameterId == "volume") list = &masterVolumeAutomation;
        else if (parameterId == "pan") list = &masterPanAutomation;
    }
    else
    {
        auto it = trackMap.find(trackId);
        if (it == trackMap.end() || !it->second)
            return "off";
        auto target = it->second->resolveAutomationTarget(parameterId, false);
        if (target.has_value())
            list = target->list;
    }
    if (!list)
        return "off";

    return automationModeToString(list->getMode());
}

