    resultObj->setProperty("pitchOnlyCoreTimbreCorrectionUsed", pitchOnlyCoreTimbreCorrectionUsed);
    resultObj->setProperty("pitchOnlyCoreEnvelopeMix", pitchOnlyCoreEnvelopeMix);
