juce::var AudioEngine::startAIGeneration(const juce::String& trackId,
                                         const juce::String& modelId,
                                         const juce::String& workflowId,
                                         const juce::String& paramsJSON)
{
    juce::ignoreUnused(trackId);

    auto result = std::make_unique<juce::DynamicObject>();

    if (aiTrackEngine.isRunning())
    {
        result->setProperty("started", false);
        result->setProperty("error", "Another AI generation is already in progress.");
        return juce::var(result.release());
    }

    auto aiToolsStatus = stemSeparator.getAiToolsStatus();
    if (auto* statusObject = aiToolsStatus.getDynamicObject())
    {
        if (modelId == "stable-audio-3-medium")
        {
            auto stableReady = false;
            juce::String stableMessage = "Stable Audio 3 Medium is not set up yet.";
            if (auto* musicModels = statusObject->getProperty("musicModels").getDynamicObject())
            {
                if (auto* stableModel = musicModels->getProperty("stable-audio-3-medium").getDynamicObject())
                {
                    stableReady = static_cast<bool>(stableModel->getProperty("ready"));
                    stableMessage = stableModel->getProperty("message").toString();
                }
            }

            if (! stableReady)
            {
                result->setProperty("started", false);
                result->setProperty("error", stableMessage.isNotEmpty()
                    ? stableMessage
                    : "Import Stable Audio 3 Medium from AI Tools Setup before generating.");
                return juce::var(result.release());
            }
        }
        else
        {
            const auto musicGenerationReady = static_cast<bool>(statusObject->getProperty("musicGenerationReady"));
            const auto layoutValid = static_cast<bool>(statusObject->getProperty("musicGenerationLayoutValid"));
            const auto availableProfilesVar = statusObject->getProperty("musicGenerationAvailableProfiles");
            auto hasNativeMusicProfile = true;
            if (auto* availableProfilesArray = availableProfilesVar.getArray())
            {
                if (! availableProfilesArray->isEmpty())
                {
                    hasNativeMusicProfile = false;
                    for (const auto& profile : *availableProfilesArray)
                    {
                        if (profile.toString() == "ace-diffusers")
                        {
                            hasNativeMusicProfile = true;
                            break;
                        }
                    }
                }
            }

            if (! musicGenerationReady || ! layoutValid || ! hasNativeMusicProfile)
            {
                const auto musicGenerationStatusMessage = statusObject->getProperty("musicGenerationStatusMessage").toString();
                const auto statusMessage = statusObject->getProperty("message").toString();
                const auto errorMessage = statusObject->getProperty("error").toString();
                const auto aceModelId = statusObject->getProperty("musicGenerationModelId").toString();
                const auto checkpointRoot = statusObject->getProperty("musicGenerationCheckpointRoot").toString();
                result->setProperty("started", false);
                result->setProperty(
                    "error",
                    errorMessage.isNotEmpty()
                        ? errorMessage
                        : (! hasNativeMusicProfile)
                            ? "The ACE-Step Diffusers backend is still missing required music-generation assets. Retry AI Tools install to finish setup."
                        : musicGenerationStatusMessage.isNotEmpty()
                            ? musicGenerationStatusMessage
                        : (! layoutValid && aceModelId.isNotEmpty() && checkpointRoot.isNotEmpty())
                            ? "ACE-Step Diffusers model " + aceModelId + " is not ready in " + checkpointRoot + "."
                            : statusMessage);
                return juce::var(result.release());
            }
        }
    }

    auto outputDir = juce::File::getSpecialLocation(juce::File::tempDirectory)
        .getChildFile("OpenStudio")
        .getChildFile("generated-music");

    if (! aiTrackEngine.startGeneration(modelId, workflowId, paramsJSON, outputDir))
    {
        auto progress = aiTrackEngine.pollProgress();
        result->setProperty("started", false);
        result->setProperty("error", progress.error.isNotEmpty()
                                         ? progress.error
                                         : "Failed to start AI generation.");
        return juce::var(result.release());
    }

    result->setProperty("started", true);
    return juce::var(result.release());
}

juce::var AudioEngine::getAIGenerationProgress()
{
    auto obj = std::make_unique<juce::DynamicObject>();
    auto progress = aiTrackEngine.pollProgress();

    obj->setProperty("state", progress.state);
    obj->setProperty("progress", static_cast<double>(progress.progress));
    obj->setProperty("phase", progress.phase);
    obj->setProperty("message", progress.message);
    obj->setProperty("backend", progress.backend);
    if (progress.modelId.isNotEmpty())
        obj->setProperty("modelId", progress.modelId);
    if (progress.workflowId.isNotEmpty())
        obj->setProperty("workflowId", progress.workflowId);
    if (progress.sourceClipId.isNotEmpty())
        obj->setProperty("sourceClipId", progress.sourceClipId);
    obj->setProperty("elapsedMs", progress.elapsedMs);
    obj->setProperty("heartbeatTs", progress.heartbeatTs);
    if (progress.phaseProgress >= 0.0)
        obj->setProperty("phaseProgress", progress.phaseProgress);
    if (progress.etaMs >= 0.0)
        obj->setProperty("etaMs", progress.etaMs);
    if (progress.runMode.isNotEmpty())
        obj->setProperty("runMode", progress.runMode);
    if (progress.runtimeProfile.isNotEmpty())
        obj->setProperty("runtimeProfile", progress.runtimeProfile);
    if (progress.lmModel.isNotEmpty())
        obj->setProperty("lmModel", progress.lmModel);
    if (progress.statusNote.isNotEmpty())
        obj->setProperty("statusNote", progress.statusNote);
    if (progress.failureKind.isNotEmpty())
        obj->setProperty("failureKind", progress.failureKind);
    if (progress.sessionMode.isNotEmpty())
        obj->setProperty("sessionMode", progress.sessionMode);
    if (progress.workerExitCode != 0)
        obj->setProperty("workerExitCode", progress.workerExitCode);
    if (progress.lastStdoutLine.isNotEmpty())
        obj->setProperty("lastStdoutLine", progress.lastStdoutLine);
    if (progress.lastStderrLine.isNotEmpty())
        obj->setProperty("lastStderrLine", progress.lastStderrLine);
    if (progress.attemptMode.isNotEmpty())
        obj->setProperty("attemptMode", progress.attemptMode);
    if (progress.attemptIndex > 0)
        obj->setProperty("attemptIndex", progress.attemptIndex);
    if (progress.protocolVersion > 0)
        obj->setProperty("protocolVersion", progress.protocolVersion);
    if (progress.scriptVersion.isNotEmpty())
        obj->setProperty("scriptVersion", progress.scriptVersion);
    if (progress.requestId.isNotEmpty())
        obj->setProperty("requestId", progress.requestId);
    if (progress.priorFailure.isNotEmpty())
        obj->setProperty("priorFailure", progress.priorFailure);
    if (progress.lastProgressAgeMs >= 0.0)
        obj->setProperty("lastProgressAgeMs", progress.lastProgressAgeMs);
    if (progress.tracePath.isNotEmpty())
        obj->setProperty("tracePath", progress.tracePath);
    if (progress.failureDetail.isNotEmpty())
        obj->setProperty("failureDetail", progress.failureDetail);
    if (progress.lmBackend.isNotEmpty())
        obj->setProperty("lmBackend", progress.lmBackend);
    if (progress.lmStage.isNotEmpty())
        obj->setProperty("lmStage", progress.lmStage);

    if (progress.outputFile.isNotEmpty())
    {
        obj->setProperty("outputFile", progress.outputFile);

        juce::File generatedFile(progress.outputFile);
        if (generatedFile.existsAsFile())
        {
            peakCache.generateAsync(generatedFile, [generatedFile]() {
                juce::Logger::writeToLog("PeakCache: Generated peaks for AI clip " + generatedFile.getFileName());
            });
        }
    }

    if (progress.error.isNotEmpty())
        obj->setProperty("error", progress.error);

    return juce::var(obj.release());
}

void AudioEngine::cancelAIGeneration()
{
    aiTrackEngine.cancel();
}

// =============================================================================
// Phase 9: ARA Plugin Hosting
// =============================================================================

juce::var AudioEngine::initializeARAForTrack(const juce::String& trackId, int fxIndex)
{
    auto obj = std::make_unique<juce::DynamicObject>();

    auto it = trackMap.find(trackId);
    if (it == trackMap.end())
    {
        obj->setProperty("success", false);
        obj->setProperty("error", "Track not found: " + trackId);
        return juce::var(obj.release());
    }

    auto* track = it->second;
    bool success = track->initializeARA(fxIndex, currentSampleRate, getSafeHostedPluginBlockSize(currentBlockSize));

    obj->setProperty("success", success);
    if (!success)
        obj->setProperty("error", "Failed to initialize ARA. Plugin may not support ARA.");

    return juce::var(obj.release());
}

juce::var AudioEngine::addARAClip(const juce::String& trackId, const juce::String& clipId)
{
    auto obj = std::make_unique<juce::DynamicObject>();

    auto it = trackMap.find(trackId);
    if (it == trackMap.end() || !it->second->hasActiveARA())
    {
        obj->setProperty("success", false);
        obj->setProperty("error", "Track not found or ARA not active.");
        return juce::var(obj.release());
    }

    // Find the clip's audio file
    auto clips = playbackEngine.getClipSnapshot();
    const PlaybackEngine::ClipInfo* foundClip = nullptr;
    for (const auto& clip : clips)
    {
        if (clip.trackId == trackId && clip.clipId == clipId)
        {
            foundClip = &clip;
            break;
        }
    }

    if (!foundClip || !foundClip->audioFile.existsAsFile())
    {
        obj->setProperty("success", false);
        obj->setProperty("error", "Clip audio file not found.");
        return juce::var(obj.release());
    }

    logToDisk("addARAClip: file=" + foundClip->audioFile.getFullPathName()
        + " exists=" + juce::String(foundClip->audioFile.existsAsFile() ? 1 : 0)
        + " start=" + juce::String(foundClip->startTime)
        + " dur=" + juce::String(foundClip->duration)
        + " offset=" + juce::String(foundClip->offset));

    auto* ara = it->second->getARAController();

    // Deactivate the plugin while holding the callback lock.
    // ARA requires the plugin to be in an unprepared state when adding
    // PlaybackRegions to renderers. Without the lock, releaseResources()
    // triggers an audio device restart cascade.
    int araFxIdx = it->second->getARAFXIndex();
    auto* araPlugin = (araFxIdx >= 0) ? it->second->getTrackFXProcessor(araFxIdx) : nullptr;

    if (araPlugin != nullptr)
    {
        const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
        araPlugin->releaseResources();
        logToDisk("addARAClip: plugin deactivated (releaseResources)");
    }

    auto sourceId = ara->addAudioSource(foundClip->audioFile, clipId,
                                         foundClip->startTime, foundClip->duration,
                                         foundClip->offset);

    // Reactivate the plugin after regions are added
    if (araPlugin != nullptr)
    {
        const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
        double sr = currentSampleRate > 0 ? currentSampleRate : 44100.0;
        int bs = getSafeHostedPluginBlockSize(currentBlockSize);
        const bool forceFloat = it->second->getTrackFXPrecisionOverride(araFxIdx);
        prepareHostedProcessorPreservingLayout(araPlugin, sr, bs,
            forceFloat ? ProcessingPrecisionMode::Float32 : processingPrecisionMode);
        logToDisk("addARAClip: plugin reactivated (prepareToPlay sr=" + juce::String(sr) + " bs=" + juce::String(bs) + ")");

        // Warmup: call processBlock with isPlaying=true to initialize the ARA
        // renderer's internal state. Without this, editing notes before the first
        // play causes ~300ms/block because the renderer hasn't been initialized.
        {
            struct WarmupPlayHead : juce::AudioPlayHead
            {
                double sr = 44100.0;
                double pos = 0.0;
                int blockSz = 512;

                juce::Optional<PositionInfo> getPosition() const override
                {
                    PositionInfo info;
                    info.setIsPlaying (true);
                    info.setTimeInSeconds (pos);
                    info.setTimeInSamples (static_cast<juce::int64> (pos * sr));
                    info.setBpm (120.0);
                    juce::AudioPlayHead::TimeSignature ts;
                    ts.numerator = 4;
                    ts.denominator = 4;
                    info.setTimeSignature (ts);
                    return info;
                }
            };

            WarmupPlayHead warmupHead;
            warmupHead.sr = sr;
            warmupHead.blockSz = bs;

            araPlugin->setPlayHead (&warmupHead);

            juce::AudioBuffer<float> warmupBuf (2, bs);
            juce::MidiBuffer warmupMidi;
            constexpr int warmupBlocks = 8;

            for (int i = 0; i < warmupBlocks; ++i)
            {
                warmupBuf.clear();
                araPlugin->processBlock (warmupBuf, warmupMidi);
                warmupHead.pos += static_cast<double> (bs) / sr;
            }

            // Restore AudioEngine as playhead
            araPlugin->setPlayHead (this);
            logToDisk ("addARAClip: renderer warmup complete (" + juce::String (warmupBlocks) + " blocks)");
        }
    }

    logToDisk("addARAClip: result=" + juce::String(sourceId.isNotEmpty() ? "OK" : "FAILED"));

    obj->setProperty("success", sourceId.isNotEmpty());
    if (sourceId.isEmpty())
        obj->setProperty("error", "Failed to add audio source to ARA document. Only WAV files are supported.");

    return juce::var(obj.release());
}

juce::var AudioEngine::removeARAClip(const juce::String& trackId, const juce::String& clipId)
{
    auto obj = std::make_unique<juce::DynamicObject>();

    auto it = trackMap.find(trackId);
    if (it == trackMap.end() || !it->second->hasActiveARA())
    {
        obj->setProperty("success", false);
        return juce::var(obj.release());
    }

    it->second->getARAController()->removeAudioSource(clipId);
    obj->setProperty("success", true);
    return juce::var(obj.release());
}

juce::var AudioEngine::getARAStatusForTrack(const juce::String& trackId) const
{
    auto obj = std::make_unique<juce::DynamicObject>();
    auto it = trackMap.find(trackId);
    if (it == trackMap.end() || it->second == nullptr)
    {
        obj->setProperty("active", false);
        obj->setProperty("activeFxIndex", -1);
        obj->setProperty("lastAttemptFxIndex", -1);
        obj->setProperty("lastAttemptComplete", false);
        obj->setProperty("lastAttemptWasARAPlugin", false);
        obj->setProperty("lastAttemptSucceeded", false);
        obj->setProperty("error", "Track not found.");
        return juce::var(obj.release());
    }

    auto* track = it->second;
    obj->setProperty("active", track->hasActiveARA());
    obj->setProperty("activeFxIndex", track->getARAFXIndex());
    obj->setProperty("lastAttemptFxIndex", track->getARALastAttemptFXIndex());
    obj->setProperty("lastAttemptComplete", track->isARALastAttemptComplete());
    obj->setProperty("lastAttemptWasARAPlugin", track->wasARALastAttemptForARAPlugin());
    obj->setProperty("lastAttemptSucceeded", track->didARALastAttemptSucceed());
    const auto debugSnapshot = track->getARADebugSnapshot();
    obj->setProperty("analysisProgress", debugSnapshot.analysisProgress);
    obj->setProperty("analysisComplete", debugSnapshot.analysisComplete);
    obj->setProperty("analysisRequested", debugSnapshot.analysisRequested);
    obj->setProperty("analysisStarted", debugSnapshot.analysisStarted);
    obj->setProperty("lastAnalysisProgressValue", debugSnapshot.lastAnalysisProgressValue);
    obj->setProperty("sourceCount", debugSnapshot.sourceCount);
    obj->setProperty("playbackRegionCount", debugSnapshot.playbackRegionCount);
    obj->setProperty("audioSourceSamplesAccessEnabled", debugSnapshot.audioSourceSamplesAccessEnabled);
    obj->setProperty("editorRendererAttached", debugSnapshot.editorRendererAttached);
    obj->setProperty("playbackRendererAttached", debugSnapshot.playbackRendererAttached);
    obj->setProperty("error", track->getARALastAttemptError());
    return juce::var(obj.release());
}

juce::var AudioEngine::shutdownARAForTrack(const juce::String& trackId)
{
    auto obj = std::make_unique<juce::DynamicObject>();

    auto it = trackMap.find(trackId);
    if (it == trackMap.end())
    {
        obj->setProperty("success", false);
        return juce::var(obj.release());
    }

    it->second->shutdownARA();
    obj->setProperty("success", true);
    return juce::var(obj.release());
}

bool AudioEngine::isARAActiveForTrack(const juce::String& trackId) const
{
    auto it = trackMap.find(trackId);
    if (it == trackMap.end() || !it->second)
        return false;
    return it->second->hasActiveARA();
}
